							data_max = std::max( data_max, wh.first * wh.second );

						}



					}else data[i][l].push_back( wh = WH( 1, 1 ) ), data_max = std::max( data_max, wh.first * wh.second );

				}	

			}

		}



		std::cout << data_max << std::endl;

 	}

	return 0;

