	Node *prev;

	Node *next;

	Node(int v) {

		val=v;

		prev=next=NULL;

	}

};

Node *head=NULL,*tail=NULL;

void add(int val) {

	Node *New=new Node(val);

	if(head==NULL) {

		head=tail=New;

	}else {

		tail->next=New;

		New->prev=tail;

		tail=New;

	}

}

void del(Node *node) {

	if(node->prev!=NULL) {

		node->prev->next=node->next;

	}else {

		head=node->next;

	}

	if(node->next!=NULL) {

		node->next->prev=node->prev;

	}else {

		tail=node->prev;

	}

	delete node;

}

