  int N, H;

  cin >> N >> H;

  REP(i,N-1) {

    scanf("%d%d",di+i,hi+i);

  }

  SegMax st(N);

  priority_queue<pii> Q;

  int now = H;

  ll ans = 0;

  REP(i,N-1) {

    st.add(i,i+1,now);

    Q.push(pii(hi[i], i));

    now -= di[i];

