            for (int j = w-1; j >= 0; j--) {

                if (rows[i][j] >= 'A') continue;

                if (rows[i][j] == '0') {

                    auto ls = { len[i+1][j], len[i][j+1] };

                    len[i][j] = "0" + *max_element(all(ls), less_than);



                    auto as = { amt[i+1][j], amt[i][j+1] };

