#define all(a) (a).begin(),(a).end()

#define pb(a) push_back((a))

#define mp(a,b) make_pair((a),(b))

#define fst first

#define sec second



using namespace std;



void split(string in,string& s1,string& s2){

  for(int i=0;i<in.size();i++){

    if(in[i]=='-'){

      s1=in.substr(0,i);

      s2=in.substr(i+1,in.size()-i-1);

      return;

    }

  }

}



bool eq_str(const string& p,const string& q){ p==q; }



multimap<string,string>m1,m2;

map<string,int>color;



void dfs(string v,int c){

  color[v]=c;

  multimap<string,string>::iterator it=m2.begin();

  while(it!=m2.end()){

    if((*it).fst==v && color[(*it).sec]==0)dfs((*it).sec,-c);

    it++;

  }

}



int graph[300][300];



void warshall_floyd(int V){

  for(int k=0;k<V;k++)

    for(int i=0;i<V;i++)

      for(int j=0;j<V;j++)

    graph[i][j]|=graph[i][k]&graph[k][j];

}



int main(void){

  int n,m;

  string in,s1,s2;

  vector<string>node,node3;

  map<string,int>node2;

  vector<pair<string,string> >query;



  while(cin >> n,n){

    m1.clear();

    m2.clear();

    color.clear();

    node.clear();

    node2.clear();

    node3.clear();

    query.clear();



    for(int i=0;i<n;i++){

      cin >> in;

      split(in,s1,s2);

      node.pb(s1);

      node.pb(s2);

      node3.pb(s1);

      node3.pb(s2);

      m1.insert(mp(s1,s2));

      //m1.insert(mp(s2,s1));

      m2.insert(mp(s1,s2));

      m2.insert(mp(s2,s1));

    }

    sort(all(node));

    node.erase(unique(all(node)),node.end());



    cout << node.size() << endl;



    //for(int i=0;i<node.size();i++)cout << node[i] << endl;



    cin >> m;

    for(int i=0;i<m;i++){

      cin >> in;

      split(in,s1,s2);

      query.pb(mp(s1,s2));

      node3.pb(s1);

      node3.pb(s2);

    }



    sort(all(node3));

    node3.erase(unique(all(node3)),node3.end());



