      node2[node3[i]]=i;

    }



    for(int i=0,j=1;i<node3.size();i++)

      if(color[node3[i]]==0)dfs(node3[i],j++);



    bool g[300][300];

    for(int i=0;i<300;i++){

      for(int j=0;j<300;j++){

	g[i][j]=false;

	graph[i][j]=i==j?1:0; 

      }

    }



    multimap<string,string>::iterator it=m1.begin(),it2=m1.begin();



    while(it!=m1.end()){

      it2=m1.begin();

