	if(it==it2){

	  it2++;

	  continue;

	}

	if((*it).fst==(*it2).sec){

	  g[node2[(*it).sec]][node2[(*it2).fst]]=true;

	  g[node2[(*it2).fst]][node2[(*it).sec]]=true;

	}

	if((*it).sec==(*it2).fst){

	  g[node2[(*it).fst]][node2[(*it2).sec]]=true;

	  g[node2[(*it2).sec]][node2[(*it).fst]]=true;

	}

	it2++;

      }

      it++;

    }



