void Pxem::addition(){

	if(pStack.size()<2)return;

	int aa=pStack.top();

	pStack.pop();

	int bb=pStack.top();

	pStack.pop();

	pStack.push(aa+bb);

}

void Pxem::subtraction(){

	if(pStack.size()<2)return;

	int aa=pStack.top();

	pStack.pop();

	int bb=pStack.top();

	pStack.pop();

	pStack.push(abs(aa-bb));

}

void Pxem::multiplication(){

	if(pStack.size()<2)return;

	int aa=pStack.top();

	pStack.pop();

	int bb=pStack.top();

	pStack.pop();

	pStack.push(aa*bb);

}

void Pxem::getQuotient(){

	if(pStack.size()<2)return;

	int aa=pStack.top();

	pStack.pop();

	int bb=pStack.top();

	pStack.pop();

	pStack.push(aa>bb?aa/bb:bb/aa);

}

void Pxem::getSurplus(){

	if(pStack.size()<2)return;

	int aa=pStack.top();

	pStack.pop();

	int bb=pStack.top();

	pStack.pop();

	pStack.push(aa>bb?aa%bb:bb%aa);

}

void Pxem::addStr(char* str){

	int leng=strlen(str);

	while(leng--)pStack.push((int)str[leng]);

}

