        P p = q.top();

        q.pop();



        to t = p.scd;



        if (p.fst > d[t.type][t.y][t.x]) continue;



        for (int i = 0; i < G[t.type][t.y][t.x].size(); ++i) {

            edge e = G[t.type][t.y][t.x][i];



