double dijkstra(const Graph &g, int s, int t) {

  int n = g.size();

  REP(i,n) REP(j,n) REP(k,32) dist[i][j][k] = INF;

  priority_queue<Edge> Q;

  Q.push(Edge(s,s,0,0));

  int cnt = 0;

  while(!Q.empty()) {

    Edge e = Q.top(); Q.pop();

    if (e.dst == t && e.c == 1) break;

    REP(k,3) {

