void solve(int *min,int flag,int c){

	int i;

	static int sum = 0, count = 0;

	if(count + 1 < *min && sum < n){

		for(i = 0;((i + 1) * (i + 2) * (i + 3)) / 6 + sum <= n && i < c;i++);

