		for(int i = 0; i < n; ++i) {

			for(int j = 0; j < n; ++j) {

				if(!to_goal[j]) {

					for(int k = 0; k < (int)es[j].size(); ++k) {

						if(to_goal[es[j][k].to]) {

							to_goal[j] = true;

							break;

						}

					}

				}

			}

		}



		cout << dijkstra(s, g) << endl;

	}



	return EXIT_SUCCESS;

