struct dice {

	int top;

	int bottom;

	int front;

	int back;

	int left;

	int right;

};



void rotate_front(dice* d) {

	int tmp = d->top;

	d->top = d->back;

	d->back = d->bottom;

	d->bottom = d->front;

	d->front = tmp;

}



void rotate_back(dice* d) {

	int tmp = d->top;

	d->top = d->front;

	d->front = d-> bottom;

	d->bottom = d-> back;

	d->back = tmp;

}



void rotate_right(dice* d) {

	int tmp = d->top;

	d->top = d->left;

	d->left = d->bottom;

	d->bottom = d->right;

	d->right = tmp;

}



void rotate_left(dice* d) {

	int tmp = d->top;

	d->top = d->right;

	d->right = d->bottom;

	d->bottom = d->left;

	d->left = tmp;

}



// t=top, f=front

void decide_all_aspects(dice* d, int t, int f) {

	d->top = t;

	d->front = f;

	d->bottom = 7 - t;

	d->back = 7 - f;

	if (t == 1) {

		if (f == 2)d->right = 3;

		if (f == 3)d->right = 5;

		if (f == 5)d->right = 4;

		if (f == 4)d->right = 2;

	}

	if (t == 2) {

		if (f == 1)d->right = 4;

		if (f == 4)d->right = 6;

		if (f == 6)d->right = 3;

		if (f == 3)d->right = 1;

	}

	if (t == 3) {

		if (f == 1)d->right = 2;

		if (f == 2)d->right = 6;

		if (f == 6)d->right = 5;

		if (f == 5)d->right = 1;

	}

	if (t == 4) {

		if (f == 1)d->right = 5;

		if (f == 5)d->right = 6;

		if (f == 6)d->right = 2;

		if (f == 2)d->right = 1;

	}

	if (t == 5) {

		if (f == 1)d->right = 3;

		if (f == 3)d->right = 6;

		if (f == 6)d->right = 4;

		if (f == 4)d->right = 1;

	}

	if (t == 6) {

		if (f == 2)d->right = 4;

		if (f == 4)d->right = 5;

		if (f == 5)d->right = 3;

		if (f == 3)d->right = 2;

	}

	d->left = 7 - d->right;

}



