void roll(dice* d){

	int z=siz[50][50];

	int nx=50,ny=50;

	while(1){

		int move=-1,mob=-1;

		for(int i=0;i<4;i++){

			int nnx=nx+dx[i],nny=ny+dy[i];

			if(i==0 && z>siz[nny][nnx] && d->right>3){

				if(mob<d->right){

					move=0;

					mob=d->right;

				}

			}

			if(i==1 && z>siz[nny][nnx] && d->back>3){

				if(mob<d->back){

					move=1;

					mob=d->back;

				}

			}

			if(i==2 && z>siz[nny][nnx] && d->left>3){

				if(mob<d->left){

					move=2;

					mob=d->left;

				}

			}

			if(i==3 && z>siz[nny][nnx] && d->front>3){

				if(mob<d->front){

					move=3;

					mob=d->front;

				}

			}

		}

		if(move==-1){

			z=siz[ny][nx];

			fie[ny][nx][z]=d->top;

			siz[ny][nx]++;

