			COST[0][i] = 0;



		for(int i=0; i<C; i++)

		for(int j=1; j<P[i]; j++)

		for(int k=Q[i][j-1]+1; k<=Q[i][j]; k++) 

			COST[k][i] = COST[k-1][i] + R[i][j - 1];





