typedef double R;



const R eps = 1e-8;

const R inf = 1e12;

typedef complex<R> P;

namespace std {

    bool operator < (const P& a, const P& b) {

        return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);

    }

}

R cross(const P& a, const P& b) {

    return imag(conj(a)*b);

}

R dot(const P& a, const P& b) {

    return real(conj(a)*b);

}



struct L : public vector<P> {

    L(const P &a = P(), const P &b = P()) {

        push_back(a); push_back(b);

    }

    // ax+by+c=0

    L(R a, R b, R c){

        if(fabs(a) < eps) *this = L(P(0,-c/b),P(1,-c/b));

        else if(fabs(b) < eps) *this = L(P(-c/a,0),P(-c/a,1));

        else *this = L(P(-c/a,0), P(0,-c/b));

    }

};



typedef vector<P> G;



struct C {

    P p; R r;

    C(const P &p, R r) : p(p), r(r) { }

    C(){}

};

bool debug = false;

struct VS {

    vector<string> ls;

    int cnt;

    double POINT_SIZE;

    double max_x, min_x, max_y, min_y;

    static char buf[2048];



    void chboundary(const C& c){

        max_x = max<double>(max_x, c.p.real() + c.r);

        max_y = max<double>(max_y, c.p.imag() + c.r);

        min_x = min<double>(min_x, c.p.real() - c.r);

        min_y = min<double>(min_y, c.p.imag() - c.r);

    }



    VS() : cnt(1), POINT_SIZE(1) { min_x = min_y = +inf; max_x = max_y = -inf; }

    VS& clear(){ return *this = VS(); }



    // 円

    VS& append(C const& c, const char* color = "black"){

        chboundary(c);

        sprintf(buf, "set object %d circle at %lf,%lf size %lf fc rgb \"%s\"",

                cnt++, (double)c.p.real(), (double)c.p.imag(), (double)c.r, color);

        ls.push_back(buf);

        return *this;

    }



    // 点

    VS& append(P const& p, const char* color = "black"){

        return append(C(p,POINT_SIZE), color);

    }



    // 多角形

    VS& append(G const& g, const char* color = "black"){

        string s;

        sprintf(buf, "set object %d polygon", cnt++);

        s += buf;

        rep(i,g.size()){

            chboundary(C(g[i],1));

            sprintf(buf, " %s %lf,%lf", i==0 ? "from" : "to",

                    (double)g[i].real(), (double)g[i].imag());

            s += buf;

        }

        sprintf(buf,

                " to %lf,%lf fc rgb \"%s\"",

                (double)g.front().real(), (double)g.front().imag(), color);

        s += buf; ls.push_back(s);

        return *this;

    }



    // 線分

    VS& append(L const& l, const char* color = "black"){

        return append(G{l[0],l[1]}, color);

    }



