    VS& append(string const& s){

        ls.push_back(s); return *this;

    }



    // 出力

    VS& plot(string png_name = "plt.png"){

        if(!debug) return *this;

        FILE* fp = popen("gnuplot -persist", "w");

        // FILE* fp = stdout;

        // FILE* fp = fopen((png_name + ".plt").c_str(), "w");

        {

            double wy = max_y-min_y, wx = max_x-min_x;

            double d = abs(wy-wx);

            if(wy > wx){

                max_x += d/2; min_x -= d/2;

            } else {

                max_y += d/2; min_y -= d/2;

            }

