	bit(int n) : v(n + 1) {}

	ll sum(int i) {

		ll res = 0;

		for (; i > 0; i -= i & -i) res += v[i];

		return res;

	}

	void add(int i, ll x) {

		for (i++; i < v.size(); i += i & -i) v[i] += x;

	}

	int lower_bound(ll x) {

		if (x <= 0) return 0;

		int res = 0;

		for (int i = 1 << 24; i > 0; i >>= 1)

			if (res + i < v.size() && v[res + i] < x) {

				res += i; x -= v[res];

			}

		return res + 1;

	}

};



int main() {

	for (;;) {

		int n, k, m; cin >> n >> k >> m;

		if (n == 0) break;

		bit b(n);

		for (int i = 0; i < n; i++) b.add(i, 1);

		for (n--; n > 0; n--) {

			b.add(m - 1, -1);

			int x = (b.sum(m) + k) % n;

			if (x == 0) x = n;

			m = b.lower_bound(x);

		}

		cout << m << endl;

	}

}

