    Point A = curr(P, i), B = next(P, i);

    if(ccw(l[0], l[1], A) != -1) Q.push_back(A); //Aが直線lの右側でない

    if(ccw(l[0], l[1], A) * ccw(l[0], l[1], B) < 0)

      Q.push_back(crosspointLL(l, Line(A, B)));

  }

  return Q;

}

