    if(is_cp(a,l)){

      P cp = line_cp(a,l);

      if(!EQ(cp,p[id][i]))res.push_back(cp);

    }else if(para(a,l) && ccw(l.fs,l.sc,a.sc)==0){

      res.push_back(a.sc);

    }

  }



  if(res.size()<2)return 0;

  return abs(res[0]-res[1]);

}



inline D f(D x){

  return len(x/2,0) * len(x/2,1);

}



