    int c=edge[i].first;

    if(U.same(a,b)||used[i])continue;

    used[i]=1;

    U.unite(a,b);

    res+=c;

  }

  for(int i=0;i<n;i++)if(!U.same(0,i))return -1;

  return res;

}



