	d[s] = 0;

	que.push(P(0,s));

	while (!que.empty()) {

		P p = que.top(); que.pop();

		ll v = p.second;

		if (d[v] < p.first) continue;

		for (auto e:G[v]){

			if (d[e.to] > d[v] + e.cost) {

				d[e.to] = d[v] + e.cost;

				que.push(P(d[e.to],e.to));

			}			

		}

	}

