bool ispath(int s) {

    if (g2[s].size() >= 2) return false;

    if (g2[s].size() == 0) return true;

    int b = -1;

    int p = s;

    while (true) {        

        for (int d: g2[p]) {

            if (d == b) continue;

            b = p;

            p = d;

            break;

        }

        if (g2[p].size() == 1) return true;

        if (g2[p].size() > 2) return false;        

    }

}



