vector<int> linear_division(const VP &p){

    int n = p.size();

    vector<int> ret;

    for(int i=0; i<n; i++){

        for(int j=i+1; j<n; j++){

            int div = 0;

            vector<pair<P, int> > online;

            for(int k=0; k<n; k++){

                if(ccw(p[i], p[j], p[k]) == 1){

                    div |= 1<<k;

                }else if(ccw(p[i], p[j], p[k]) != -1){

                    online.emplace_back(p[k], k);

                }

            }

            sort(online.begin(), online.end());

            for(int d=0; d<2; d++){

                for(int k=0; k<(int)online.size(); k++){

                    div ^= 1<<online[k].second;

                    if((div & 1) == 0){

                        ret.push_back(div ^ ((1<<n) -1));

                    }else{

                        ret.push_back(div);

                    }

                }

            }

        }

    }

    sort(ret.begin(), ret.end());

    ret.erase(unique(ret.begin(), ret.end()), ret.end());

    return ret;

}



vector<long long int> circle_division(const VP &p, const vector<edge> &e){

    int m = e.size();

    vector<C> c(m);

    for(int i=0; i<m; i++){

        c[i] = C(p[e[i].from], abs(p[e[i].from] -p[e[i].to]));

    }

    vector<vector<double> > cpa(m);

    for(int i=0; i<m; i++){

        for(int j=0; j<m; j++){

            VP cp = crosspointCC(c[i], c[j]);

            for(const P &point: cp){

                cpa[i].push_back(arg(point -c[i].p));

            }

        }

        cpa[i].push_back(-PI);

        cpa[i].push_back(PI);

        sort(cpa[i].begin(), cpa[i].end());

    }



    VP cand;

    for(int i=0; i<m; i++){

        for(int j=0; j<(int)cpa[i].size()-1; j++){

            double angle = (cpa[i][j] +cpa[i][j+1]) /2;

            P rot = rotate(P(c[i].r, 0), angle);

            cand.push_back(c[i].p +rot +unit(rot)*EPS*10.0);

            cand.push_back(c[i].p +rot -unit(rot)*EPS*10.0);

        }

    }



    vector<long long int> ret;

    for(const P &point: cand){

        long long int div = 0;

        for(int i=0; i<m; i++){

            if(abs(point -c[i].p) < c[i].r +EPS){

                div |= 1LL<<i;

            }

        }

        ret.push_back(div);

    }

    sort(ret.begin(), ret.end());

    ret.erase(unique(ret.begin(), ret.end()), ret.end());

    return ret;

}



double solve_onewarp(const VP &p, const vector<edge> &e, long long int ldiv, const vector<long long int> &cdiv){

    int m = e.size();

    double ret = INF;

    for(long long int inout: cdiv){

        double weight = 0;

        P g(0, 0);

        for(int i=0; i<m; i++){

            if((1<<e[i].from & ldiv) == 0) continue;

            if((1LL<<i & inout) != 0){

                double w = 1/e[i].v /e[i].v;

                g += w *p[e[i].from];

                weight += w;

            }

        }

        g /= weight;

        double sub = 0;

        for(int i=0; i<m; i++){

            if((1<<e[i].from & ldiv) == 0) continue;

            if((1LL<<i & inout) != 0){

                sub += norm((p[e[i].from] -g) /e[i].v);

            }else{

                sub += norm((p[e[i].from] -p[e[i].to]) /e[i].v);

            }

        }

        ret = min(ret, sub);

    }

    return ret;

}



double solve_twowarp(const VP &p, const vector<edge> &e){

    vector<int> ldiv = linear_division(p);

    vector<long long int> cdiv = circle_division(p, e);

    double ret = INF;

    for(int bit: ldiv){

        int revbit = bit ^((1<<p.size()) -1);

        ret = min(ret, solve_onewarp(p, e, bit, cdiv) +solve_onewarp(p, e, revbit, cdiv));

    }

    return sqrt(ret /e.size());

}



