      REP(i, N)REP(j, N)if((state >> i & 1) != (state >> j & 1)){

        int nst = state ^ (1 << i) ^ (1 << j);

        int nd = d + abs(i - u) + abs(j - i);

        int nu = j;

        if(dist[nst][nu] > nd){

          dist[nst][nu] = nd;

          que.push(S(nd * -1, P(nst, nu)));

        }

      }

    }

  }

  return 0;

}

