	for(int T=1;scanf("%d",&n),n;T++){

		rep(i,n)	scanf("%d",c+i);



		if(c[0]!=1){

			printf("Case #%d: Cannot pay some amount\n",T);

			continue;

		}



		const int L=100*c[n-1];

		dp1[0]=0;

		fill(dp1+1,dp1+L,INF);

		rep(k,n)for(int p=c[k];p<L;p++)	dp1[p]=min(dp1[p],dp1[p-c[k]]+1);



		dp2[0]=0;

		fill(dp2+1,dp2+L,INF);

		rep(p,L)for(int k=n-1;k>=0;k--){

			if(p-c[k]>=0){

				dp2[p]=dp2[p-c[k]]+1;

				break;

			}

		}



		bool ok=true;

		rep(i,L)if(dp1[i]<dp2[i]){ ok=false; break; }

		printf("Case #%d: %s\n",T,ok?"OK":"Cannot use greedy algorithm");

	}



	return 0;

}

