inline int getval(int c,int j,int bit){

  if      (j == -1)j=0;

  else if (j ==  c)j=c-1;

  return (bit&(1<<j)) != 0;

}



inline int checkij(int r,int c,int i,int j,int bit0,int bit1,int bit2){

  int ret=0;

  int bit=0;

  //bit0

  if (i-1 < 0)bit=bit1;

  else        bit=bit0;

  REP(k,-1,2)ret+=getval(c,j+k,bit);



  //bit1

  bit=bit1;

  REP(k,-1,2)ret+=getval(c,j+k,bit);



  //bit2

  if (i+1 == r)bit=bit1;

  else         bit=bit2;

  REP(k,-1,2)ret+=getval(c,j+k,bit);

  return ret;

}



inline bool isvalid(int r,int c,int now,int bit0,int bit1,int bit2){

  rep(j,c){

    int cnt=checkij(r,c,now-1,j,bit0,bit1,bit2);

    if ((m[now-1][j] == '#'&&cnt>=5) ||

	(m[now-1][j] == '.'&&cnt<5 ));

    else return false;

  }

  return true;

}



int dp[1<<N][1<<N][N];

int dp2[1<<N][1<<N][N];

int bitcount[1<<N];



int solvemax(int r,int c,int bit0,int bit1,int now){

  if (now == r){

    return isvalid(r,c,now,bit0,bit1,0)?bitcount[bit1]:-inf;

  }

  int &ret=dp[bit0][bit1][now-1];

  if (ret == -2*inf){

    //ret=bitcount[bit1];

    ret=-inf;

    rep(i,(1<<c)){

      if (isvalid(r,c,now,bit0,bit1,i)){

	ret=max(ret,solvemax(r,c,bit1,i,now+1)+bitcount[bit1]);

      }

    }

  }

  return ret;

}





int solvemin(int r,int c,int bit0,int bit1,int now){

  if (now == r){

    return isvalid(r,c,now,bit0,bit1,0)?bitcount[bit1]:inf;

  }

  int &ret=dp2[bit0][bit1][now-1];

  if (ret == 2*inf){

    ret=inf;

    rep(i,(1<<c)){

      if (isvalid(r,c,now,bit0,bit1,i)){

	ret=min(ret,solvemin(r,c,bit1,i,now+1)+bitcount[bit1]);

      }

    }

  }

  return ret;

}



void solve(int r,int c,int bit0,int bit1,int now){

  if (now == r){

    if (isvalid(r,c,now,bit0,bit1,0)){

      dp[ bit0][bit1][now-1]=bitcount[bit1];

      dp2[bit0][bit1][now-1]=bitcount[bit1];

    }else {

      dp[ bit0][bit1][now-1] =-inf;

      dp2[bit0][bit1][now-1]= inf;

    }

    return;

  }

  int &ret= dp[ bit0][bit1][now-1];

  int &ret2=dp2[bit0][bit1][now-1];

  if (ret == -2*inf ){

    ret=-inf;

    ret2=inf;

    rep(i,(1<<c)){

      if (isvalid(r,c,now,bit0,bit1,i)){

	solve(r,c,bit1,i,now+1);

	if (dp[bit1][i][now] != -inf){

	  ret =max(ret, dp[bit1][i][now]+bitcount[bit1]);

	}

	if (dp2[bit1][i][now] != inf){

	  ret2=min(ret2,dp2[bit1][i][now]+bitcount[bit1]);

	}

      }

    }

  }

  return;

}



