  REP(k,-1,2)ret+=getval(c,j+k,bit);



  //bit1

  bit=bit1;

  REP(k,-1,2)ret+=getval(c,j+k,bit);



  //bit2

  if (i+1 == r)bit=bit1;

  else         bit=bit2;

  REP(k,-1,2)ret+=getval(c,j+k,bit);

  return ret;

}



inline bool isvalid(int r,int c,int now,int bit0,int bit1,int bit2){

  rep(j,c){

    int cnt=checkij(r,c,now-1,j,bit0,bit1,bit2);

    if ((m[now-1][j] == '#'&&cnt>=5) ||

	(m[now-1][j] == '.'&&cnt<5 ));

