void dijkstra(int s){

	priority_queue<Situation> que;

	for(int i = 0; i < MAX_V; i++)

		fill(d[i],d[i]+MAX_V,INF);

	d[s][L] = 0;

	que.push(Situation(0,s,L));

	while(!que.empty()){

		Situation p = que.top();

		que.pop();

		int node = p.node;

		int money=p.money;

		if(d[node][money] < p.cost)

