        }

        vector<VP> sq(n, VP(4));

        for(int i=0; i<n; i++){

            sq[i][0] = v[i] +P(r, 0);

            sq[i][1] = v[i] +P(0, r);

            sq[i][2] = v[i] +P(-r, 0);

            sq[i][3] = v[i] +P(0, -r);

        }



        vector<L> l;

        l.reserve(9*n);

        for(int i=0; i<n; i++){

            l.push_back(L(v[i], v[(i+1)%n]));

            for(int j=0; j<4; j++){

                l.push_back(L(sq[i][j], sq[(i+1)%n][j]));

                l.push_back(L(sq[i][j], sq[i][(j+1)%4]));

            }

        }

        vector<L> cand = arrangement(l);



        double ans = 0;

        for(int i=0; i<(int)cand.size(); i++){

            bool rem = true;

            for(int j=0; j<n; j++){

                P mid = (cand[i][0] +cand[i][1])/2.0;

                if(L1distanceSP(L(v[j], v[(j+1)%n]), mid) +EPS < r || in_poly(mid, v) == -1){

                    rem = false;

                    break;

                }

            }

            if(rem){

                ans += abs(cand[i][1] -cand[i][0]);

            }

        }

        cout << fixed;

        cout << setprecision(10);

        cout << ans << endl;

    }

    return 0;

}

