typedef	pair<int,int>	pii;



class UnionFind{

	vi a;

	int root(int x){ return ~a[x]?a[x]=root(a[x]):x; }

public:

	UnionFind(int n):a(n,-1){}

	bool find(int x,int y){ return root(x)==root(y); }

	bool unite(int x,int y){ return find(x,y)?0:(a[root(y)]=root(x),1); }

};



