ll encode(int box[2][8]) {

  ll ret = 0;

  REP(lr, 2) {

    REP(index, n) {

      ret |= (ll)box[lr][index] << (3 * (lr * 8 + index));

    }

  }

  return ret;

}

void decode(int box[2][8], ll value) {

  REP(lr, 2) {

    REP(index, n) {

      box[lr][index] = (value >> (3 * (lr * 8 + index))) & 7;

    }

  }

}

int huristic(int box[2][8]) {

  int ret1 = 0;

  REP(lr, 2) {

    REP(index, n) {

      ret1 += abs(box[lr][index] - index);

    }

  }

  ret1 /= 2;

  int ret2 = 5;

