    for(int i=0;i<m;i++)

      cin >> mx[i] >> my[i];



    for(int i=0;i<n;i++){

      cost[i].resize(m);

      for(int j=0;j<m;j++){

        cost[i][j]=dist(nx[i],ny[i],mx[j],my[j])/nv[i];

      }

    }



    double l=0,r=1e8;



    for(int i=0;i<1000;i++){

      double mid=(l+r)/2;

      int res=max_flow(mid);

      if(res==m)r=mid;

      else l=mid;

    }



    printf("%.8f\n",r);

  }



  return 0;

}

