		if(pos[u] < edge[u].size()){

			u = edge[u][pos[u] ++];

			d ++;

		}

		else{ 

			while(1){

				if(pos[u] < edge[u].size() || u == 1) break;

				for(int i = 0; i < mark[u].size(); i ++){

					int _index = mark[u][i];

					sg.modify(1, 1, m, _index, 0);

				}

				u = f[u];

				d --;

			}

			if(pos[u] < edge[u].size()){

				u = edge[u][pos[u] ++];

				d ++;

			}

			else break;

		}

	}

