            }

        }

    }

    if (abs(a - b) > a.r + b.r + EPS) {

        Point p = a * b.r + b * a.r;

        p = p * (1.0 / (a.r + b.r));

        vector<Line> bs = tanline(p, a);

        vector<Line> as = tanline(p, b);

        for (int i = 0; i < min(as.size(), bs.size()); ++i) {

            res.push_back(Line(bs[i][1], as[i][1]));

        }

    }

    return res;

