        Point p = a * b.r + b * a.r;

        p = p * (1.0 / (a.r + b.r));

        vector<Point> bs = tanline(p, a);

        vector<Point> as = tanline(p, b);

        for (int i = 0; i < min(as.size(), bs.size()); ++i) {

            res.push_back(Line(bs[i], as[i]));

        }

    }

    return res;

}









