}



int n, m, k;

struct MSQ : public G{

	MSQ(){}

	vector<P> p;

	vector<S> s;

	int m, k;

	MSQ(int m, int k):m(m), k(k){

		REP(i, m) p.push_back(polar((R)1, 2*PI*i/m + PI*(R).5));

		REP(i, m) s.emplace_back(p[i], p[(i+k)%m]);

		Arrangement a(s);

		DualGraph dg(a.p);

		REP(i, a.g.size())REP(j, a.g[i].size()){

			int u = a.g[i][j].u;

			int v = a.g[i][j].v;

			if(u < v) dg.add_edge(u, v);

		}

		(G &)(*this) = dg.dual();

		reverse(this->begin(), this->end());

	}

	void copy(R r, P c, MSQ &msq)const {

		msq.resize(size());

		msq.p.resize(p.size());

		msq.s.resize(s.size());

		msq.m = m;

		msq.k = k;

		REP(i, size())   msq[i] = at(i)*r + c;

		REP(i, p.size()) msq.p[i] = p[i]*r + c;

		REP(i, s.size()) msq.s[i] = S(msq.p[i], msq.p[(i+k)%m]);

	}

	S segment(int i)const {

		return s[i];

	}

};

int convex_contains(const MSQ &msq, const P &g, const P &p) {

	const int n = msq.size();

	int a = 0, b = n;

	while (a+1 < b) { // invariant: c is in fan g-P[a]-P[b]

		int c = (a + b) / 2;

		if (outp(msq[a]-g, p-g) > 0 && outp(msq[c]-g, p-g) < 0) b = c;

		else  a = c;

	}

	b %= n;

	if (outp(msq[a] - p, msq[b] - p) < -EPS) return 0;

	return 1;

}

bool check(const MSQ & temp, R r, const vector<P> &shoolack, int i, int j){

	MSQ msq;

	L l = temp.segment(j);

	P gp = shoolack[i] - l[0]*r;

	temp.copy(r, gp, msq);

	vector<P> p;

	P b(-INF, -INF), u(+INF, +INF);

	REP(i, n){

		L l2(shoolack[i], shoolack[i] + l.dir());

		int f = 0;

		P ll(INF, INF), rr(-INF, -INF);

		REP(j, m){

			const S s = msq.segment(j);

			if(sig(outp(s.dir(), l2.dir()))){

				const P q = crosspoint(s, l2);

				if(!s.online(q)) continue;

				p.push_back(q - l2[0]);

				ll = min(ll, p.back());

				rr = max(rr, p.back());

			}

			f = 1;

		}

		u = min(rr, u);

		b = max(ll, b);

		if(!f) return false;

	}

	FOR(q, p){

		if(S(b, u).online(*q) == FALSE) continue;

		if([&](){

			REP(i, n) if(!convex_contains(msq, gp, shoolack[i] + *q)) return 0;

			return 1;

		}()) return true;

	}

	return false;

}



int main(){

	ios::sync_with_stdio(false);

	while(cin >> n >> m >> k, n){

		MSQ temp(m, k);

		vector<P> shoolack(n);

		REP(i, n) cin >> shoolack[i];

		R best = 2000;

		REP(i, n)REP(j, m){

			if(!check(temp, best-EPS, shoolack, i, j)) continue;

			R l=EPS, r = best;

			REP(itr, 50){

