struct edge

{    int u,v,w;

   edge(int u=0,int v=0,int w=0):u(u),v(v),w(w) {}

};

struct simplex

{    double v;

   double a[1205][1205];

   double b[1205];

   double c[1205];

   int basic[1205];

   int nbasic[105];

   void pivot(int l,int e);

   double opt();

   void output();

};

int fcmp(double x)

{    if (fabs(x)<prec)

       return 0;

   return x>0?1:-1;

}

edge ed[1005];

