    scanf("%d%d",&(reqs[i].house),&(reqs[i].time));

  }

  compute_dist();//すべてのhouse間の最短距離を算出、distに記録

  sort(reqs,reqs+l,LessReq());

  compute_req_graph();//req_graphの構成

  int res = num_covers();

  return res;

}



