inline int gcd(int a, int b) {

	while (a != 0) {

		int t = b % a;

		b = a;

		a = t;

	}

	return b;

}



inline int abs(int x) {

	return x < 0 ? -x : x;

}



struct Frac {

	int a, b;

	Frac() : a(1), b(1) {}

	Frac(int a, int b) : a(a), b(b) {

		reduce();

	}

	void reduce() {

		int g = gcd(a, b);

		a /= g;

		b /= g;

	}

	bool operator < (const Frac& f) const {

		return (long long)a * f.b < (long long)b * f.a;

	}

};



