						continue;

					}

					else {

						p.second.push_back(e);

						if (p.first == now) {

							return make_pair(-1, p.second);

						}

						else {

							return p;

						}

					}

				}

			}

			return make_pair(-2, vector<Edge>(0));

		}

		else {

			assert(false);

			return make_pair(0,vector<Edge>(0));

		}

