            vector<double>L(k);

            rep(i,k)L[i]=r[i]*r[(i+1)%k]/2.0;

            double mi=*min_element(all(L));

            double lb=-mi;

            double ub=mi;

            rep(i,100){

                double mid=(ub+lb)/2;

                double sum=0;

                rep(j,k)sum+=acos(mid/L[j]);

                if(sum>=2*PI)lb=mid;

                else ub=mid;

            }



