// A->B->C と巡るときの位置関係を調べる

enum { CCW = +1, CW = -1, CAB = +2, ABC = -2, SEG = 0 };

int ccw(P a, P b, P c) {

    b -= a; c -= a;

    if (cross(b, c) > 0)   return CCW; // a->b->c 反時計回り

    if (cross(b, c) < 0)   return  CW; // a->b->c 時計回り

    if (dot(b, c) < 0)     return CAB; // c--a--b 直線上

    if (norm(b) < norm(c)) return ABC; // a--b--c 直線上

