#define e (1e-6)



P readP() {

    double x, y;

    scanf("%lf%lf", &x, &y);

    return P(x, y);

}



double radius(const vector<P>& ps) {

    P p = P(0, 0);

    for (double cur = 1.0; cur > EPS; cur *= 0.5) {

        rep (_, 100) {

            double mx = norm(ps[0]-p);

            int ix = 0;

            rep (i, ps.size()) {

                double d = norm(ps[i]-p);

                if (mx < d) mx = d, ix = i;

            }

            p += cur*(ps[ix]-p);

        }

    }

    double ans = 0;

    rep (i, ps.size()) ans = max(ans, abs(ps[i]-p));

    return ans;

}



