bool can(int k) {

    vector<double> a, b;

    rep (i, n) if (!used[i]) a.push_back(rs[i]);

    rep (i, m) if (i >= k) b.push_back(ts[i]);

    sort(a.begin(), a.end());

    reverse(a.begin(), a.end());

    sort(b.begin(), b.end());

    reverse(b.begin(), b.end());

    rep (i, b.size()) if (b[i] > a[i]+e) return false;

    return true;

}



