struct LCNode {

    typedef LCNode* NP;

    typedef int D;

    static const int INF = 1LL<<25;

    static const int DF = 1LL<<25;

    static LCNode last_d;

    static NP last;

    NP p, l, r;

    int sz;

    int v, sm, lz;

    int lsm, rsm, ma, mv;

    bool rev;

    LCNode(D v) :p(NULL), l(last), r(last), sz(1),

        v(v), sm(v), lz(DF), rev(false),

        lsm(max(v, 0)), rsm(max(v, 0)), ma(max(v, 0)), mv(v) {}

    LCNode() : l(NULL), r(NULL), sz(0), v(-INF), mv(-INF) {}

    inline int pos() {

        if (p) {

            if (p->l == this) return -1;

            if (p->r == this) return 1;

        }

        return 0;

    }

    void rot() {

        NP qq = p->p;

        int pps = p->pos();

        if (p->l == this) {

            p->l = r; r->p = p;

            r = p; p->p = this;

        } else {

            p->r = l; l->p = p;

            l = p; p->p = this;

        }

        p->update(); update();

        p = qq;

        if (!pps) return;

        if (pps == -1) {

            qq->l = this;

        } else {

            qq->r = this;

        }

        qq->update();

    }

    void splay() {

        assert(this != last);

        supush();

        int ps;

        while ((ps = pos())) {

            int pps = p->pos();

            if (!pps) {

                rot();

            } else if (ps == pps) {

                p->rot(); rot();

            } else {

                rot(); rot();

            }

        }

    }

    void expose() {

        assert(this != last);

        NP u = this;

        do {

            u->splay();

        } while ((u = u->p));

        u = last;

        u->p = this;

        do {

            u->p->r = u;

            u->p->update();

            u = u->p;

        } while (u->p);

        splay();

    }

    void push() {

        if (rev) {

            if (l->sz) {

                l->revdata();

            }

            if (r->sz) {

                r->revdata();

            }

            rev = false;

        }

        if (lz != DF) {

            if (l->sz) {

                l->lzdata(lz);

            }

            if (r->sz) {

                r->lzdata(lz);

            }

            lz = DF;

        }

    }

    void nopush() {

        assert(rev == false);

        assert(lz == DF);

    }

    void supush() {

        if (pos()) {

            p->supush();

        }

        push();

    }

    inline void revdata() {

        assert(this != last);

        swap(l, r);

        swap(lsm, rsm);

        rev ^= true;

    }

    inline void lzdata(D d) {

        assert(this != last);

        v = mv = d;

        sm = sz*d;

        lsm = rsm = ma = max(0, sm);

        lz = d;

    }

    NP update() {

        assert(this != last);

        sz = 1+l->sz+r->sz;

        sm = v+l->sm+r->sm;

        lsm = max(l->lsm, l->sm+v+r->lsm);

        rsm = max(r->rsm, r->sm+v+l->rsm);

        ma = max(l->ma, r->ma);

        ma = max(ma, l->rsm+v+r->lsm);

        mv = max(l->mv, r->mv);

        mv = max(mv, v);

        return this;

    }



    void evert() {

        expose();

        revdata();

    }

};

