inline int getint() {

    char c;

    int res = 0;

    bool neg = false;

    while (true) {

        c = getchar_unlocked();

        if (c == '-') {

            neg = true;

            break;

        }

        if ('0' <= c && c <= '9') {

            res = c-'0';

            break;

        }

    }

    while (c = getchar_unlocked(), '0' <= c && c <= '9') {

        res *= 10;

        res += c-'0';

    }

    if (neg) res *= -1;

    return res;

}



inline void putint(int d) {

    static char buf[10];

    int c = 0;

    if (d < 0) {

        putchar_unlocked('-');

        d *= -1;

    }

    if (!d) {

        putchar_unlocked('0');

        return;

    }

    while (d) {

        buf[c++] = d%10;

        d = d/10;

    }

    while (c--) {

        putchar_unlocked(buf[c]+'0');

    }

}



