        REP(i, inter_point.size()) if(abs(x - inter_point[i]) < EPS) ok = false;

        if(ok) inter_point.insert(lower_bound(inter_point.begin(), inter_point.end(), x), x);

      }

    }

    REP(i, N) FOR(j, i + 1, N) {

      vector<double> v = quadratic(a[i] - a[j], b[i] - b[j], c[i] - c[j]);

      REP(k, v.size()){

        double x = v[k];

        x = max(0.0, x);

        x = min(W, x);

