      if(!(f(a[idx], b[idx], c[idx], lb + EPS) >= - EPS)) continue;

      if(!(f(a[idx], b[idx], c[idx], ub - EPS) >= - EPS)) continue;

      //printf("[%lf, %lf] idx = %d\n", lb, ub, idx);

      double A = 2 * a[idx];

      double B = b[idx];

      const int N = 10000;

      double delta = (ub - lb) / N;

      double S = 0;

      S += g(A, B, lb) + g(A, B, ub);

      for(int i = 1; i < N; i += 2){

        S += 4.0 * g(A, B, lb + delta * i);

      }

      for(int i = 2; i < N; i += 2){

        S += 2.0 * g(A, B, lb + delta * i);

      }

      ans += S * delta / 3.0;

    }

    assert(!isnan(ans));

    printf("%.16lf\n", ans);

  }

  return 0;

}

