    cin >> n;

    wall.resize(n);

    for(int i=0; i<n; i++){

        for(P &p: wall[i]){

            input_P(p);

        }

    }

}



void misc(){

    dir.resize(rot+1);

    for(int i=0; i<rot+1; i++){

        dir[i] = rotate(P(l, 0), PI/rot *i);

    }

}



void make_slide_rect(){

    slide_rect.resize(rot);

    for(int r=0; r<rot; r++){

        for(L &w: wall){

            P vw = w[1] -w[0];

            if(isParallel(vw, dir[r])){

                slide_rect[r].push_back(make_rect(w, l *unit(vw), weps *unit(rotate(vw, PI/2))));

            }else{

                slide_rect[r].push_back(make_rect(w, weps *unit(vw), (cross(vw, dir[r]) > 0)? dir[r]: -dir[r]));

            }   

        }

    }

}



void make_nonrot_area(){

    nonrotate_area.resize(rot);

    for(int r=0; r<rot; r++){

        nonrotate_area[r].resize(n);

        for(int i=0; i<n; i++){

            auto &nr = nonrotate_area[r][i];

            nr.first.push_back(slide_rect[r][i]);

            nr.first.push_back(slide_rect[(r+1)%rot][i]);

            P vert = rotate(wall[i][1] -wall[i][0], PI/2);

            if(cross(vert, dir[r]) * cross(vert, dir[r+1]) < -EPS){

                nr.first.push_back(make_rect(wall[i], P(0, 0), l*unit(vert)));

            }

            nr.second.emplace_back(C(wall[i][0], l), dir[r], dir[r+1]);

            nr.second.emplace_back(C(wall[i][1], l), dir[r], dir[r+1]);

        }

    }

}



void enum_rotate_candidate(){

    cand_rot.resize(rot);

    for(int r=0; r<rot; r++){

        vector<vector<L>> w(n);

        for(int i=0; i<n; i++){

            auto &nr = nonrotate_area[r][i];

            for(VP &v: nr.first){

                for(int j=0; j<4; j++){

                    w[i].emplace_back(v[j], v[(j+1)%4]);

                }

            }

        }

        auto &cand = cand_rot[r];       

        for(int i=0; i<n; i++){

            for(int j=i+1; j<n; j++){

                auto &arci = nonrotate_area[r][i].second;

                auto &arcj = nonrotate_area[r][j].second;

                for(L &a: w[i]){

                    for(L &b: w[j]){

                        if(strictItsSS(a, b)){

                            cand.push_back(crosspointLL(a, b));

                        }

                    }

                }

                for(L &s: w[i]){

                    for(DA &da: arcj){

                        insertvec(cand, crosspointSDA(s, da));

                    }

                }

                for(DA &da: arci){

                    for(L &s: w[j]){

                        insertvec(cand, crosspointSDA(s, da));

                    }

                }

                for(DA &a: arci){

                    for(DA &b: arcj){

                        insertvec(cand, crosspointDADA(a, b));

                    }

                }

            }

        }

        sort(cand.begin(), cand.end());

        cand.erase(unique(cand.begin(), cand.end()), cand.end());

    } 

}



bool is_in_nonrot_area(const P &p, int r){

    for(auto &nr: nonrotate_area[r]){

        for(VP &rect: nr.first){

            if(isInConvex(p, rect)){

                return true;

            }

