				sumarea += areas[i].first;

				areas.erase(areas.begin() + i);

				break;

			}

		}

	}

	while(!areas.empty()){

		R b = search(sumarea + areas.back().first);

		tar.eb(b, areas.back().second);

		sumarea += areas.back().first;

		areas.pop_back();

