#include<iostream>

#include<algorithm>

using namespace std;

#define INF (1<<24)

int N;

int t[500],sum[500];

int dp[500][500];



int calc(int X,int Y){



  int res=0,c=-1,a,b;

  for(int I=0;I<50;I++){



    if(c==-1||c+a+b<10)c=0;

    else c=1;

    a=X%10;

    b=Y%10;

    X/=10;

    Y/=10;

    res+=(a*b+c);

  }



  return res;

}

int solve(int l,int r){



  if(dp[l][r]!=-1)return dp[l][r];

  if(l==r)return 0;

  int res=INF;

  for(int i=l;i<r;i++){



    res=min(res, solve(l,i)+solve(i+1,r)+calc(sum[i]-sum[l-1],sum[r]-sum[i]));

  }



  return dp[l][r]=res;

}



void init(){

  for(int i=0;i<500;i++){

    t[i]=sum[i]=0;

    for(int j=0;j<500;j++)dp[i][j]=-1;

  }

}



int main(){

  init();

  cin>>N;

  for(int i=1;i<=N;i++){

    cin>>t[i];

    sum[i]=t[i]+sum[i-1];

  }



  cout<<solve(1,N)<<endl;

  return 0;

}

