bigint& bigint::operator += (const bigint& x) {

  if (negative != x.negative) return *this -= -x;

  if (a.size() < x.a.size()) a.resize(x.a.size());

  int tmp = 0;

  for (int i = 0; i < a.size(); ++i) {

    a[i] += (i<x.a.size()?x.a[i]:0) + tmp;

    tmp = a[i] / BASE;

    a[i] %= BASE;

  }

  if (tmp) a.push_back(1);

