bigint& bigint::operator -= (const bigint& x) {

  if (negative != x.negative) return *this += -x;

  std::vector<int> b(x.a);

  if ((*this < x) ^ negative) {

    a.swap(b);

    negative = !negative;

  }

  for (int i = 0, tmp = 0; i < a.size(); ++i) {

    a[i] += BASE - (i<b.size()?b[i]:0) + tmp;

    tmp = a[i] / BASE - 1;

    a[i] %= BASE;

  }

  return this->normalize();

}

bigint& bigint::operator *= (const bigint& x) {

  negative ^= x.negative;

