  for (int i = 0; i < a.size(); ++i) {

    long long tmp = 0;

    for (int j = 0; j < x.a.size(); ++j) {

      long long v = (long long)a[i] * x.a[j] + c[i+j] + tmp;

      tmp = v / BASE;

      c[i+j] = (int)(v % BASE);

    }

    if (tmp) c[i+x.a.size()] += (int)tmp;

  }

  a.swap(c);

  return this->normalize();

}

