}



bool is_OK(ll number){

	stack<ll> S;

	while(number > 0){

		S.push(number%10);

		number /= 10;

	}

	int index = 0;

	ll work[4];



	while(!S.empty()){

		work[index++] = S.top();

		S.pop();

	}



	return (work[0] == 5 && work[1] == 1 && work[3] == 3);

}



ll recursive(ll pre_num,ll digit,Type type,bool is_completed){



	if(digit == length){

		if(is_completed)return 1;

		else{

			return 0; //G数が成立しないならreturn 0;

		}

	}



	if(dp[digit][pre_num][type][is_completed] != -1){

		return dp[digit][pre_num][type][is_completed]; //計算済ならreturn

	}



	if(is_completed == true && type == ELSE){

		return dp[digit][pre_num][type][is_completed] = pow(10,length-digit);

	}



	ll ret = 0;

	ll limit;

	if(type == FULL_MATCH){

		limit = num_array[digit]-1;

	}else{

		limit = 9;

	}



	ll tmp;



	for(int next = 0; next <= limit; next++){

		tmp =  getNUM(pre_num,next);

