	}



	if(type == FULL_MATCH){

		tmp = getNUM(pre_num,num_array[digit]);

		ret += recursive(tmp,digit+1,FULL_MATCH,is_completed||is_OK(tmp));

	}



	return dp[digit][pre_num][type][is_completed] = ret;

}





