    push(k, r-l);

    if(r <= a || b <= l) return;

    if(a <= l && r <= b) {

      lazy[k] = OM::op(x, lazy[k]);

      push(k, r-l);

      return;

    }

    update(a, b, x, 2*k+1, l, (l+r)/2);

