int top(int key){

    if(nd[key].parent == -1)return key;

    else return top(nd[key].parent);

}



void join(int s, int t){

    int a = top(s);

    int b = top(t);

    if(a==b)return;

    if(nd[a].height<nd[b].height){

        nd[a].parent = b;

    }else{

        nd[b].parent = a;

        if(nd[a].height==nd[b].height)nd[a].height++;

    }

    return;

}



bool isFriend(int s, int t){

    if(top(s)==top(t))return true;

    else return false;

}



