        return s;

    else

        return user[s] = root(user[s]);

}



void unite(int s, int t) {

    int rs = root(s);

    int rt = root(t);

    if (rs != rt) {

        if (user[rs] < user[rt])

            swap(rs, rt);

        user[rs] += user[rt];

        user[rt] = rs;

    }

}



bool same(int s, int t) {

    return root(s) == root(t);

}



