struct SuffixArray {

    int n, k;

    string text;

    vector<int> sa;

    vector<int> rank;

    vector<int> lcp;



    SuffixArray (const string &s)

    : text(s), n(s.size()), sa(n + 1), rank(n + 1), lcp(n)

    {}



    bool comp(int i, int j) {

        if (rank[i] != rank[j]) return rank[i] < rank[j];

        int ri = i + k <= n ? rank[i + k] : -1;

        int rj = j + k <= n ? rank[j + k] : -1;

        return ri < rj;

    }



    void construct_sa() {

        for (int i = 0; i <= n; i++) {

            sa[i] = i;

            rank[i] = i < n ? text[i] : -1;

        }



        for (k = 1; k <= n; k *= 2) {

            sort(sa.begin(), sa.end(), [&](const int& i, const int& j) {return comp(i, j);});



            vector<int> tmp(n + 1);

            tmp[sa[0]] = 0;

            for (int i = 1; i <= n; i++) {

                tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) ? 1 : 0);

            }



            for (int i = 0; i <= n; i++) {

                rank[i] = tmp[i];

            }

        }

    }



    void construct_lcp () {

        int h = 0;

        lcp[0] = 0;

        for (int i = 0; i < n; i++) {

            int j = sa[rank[i] - 1];

            if (h > 0) h--;

            for (; j + h < n && i + h < n; h++) {

                if (text[j + h] != text[i + h]) break;

            }

            lcp[rank[i] - 1] = h;

        }

    }



    int low_bd(const string &pt) {

        int l = 0, r = n + 1;

        while (r - l > 1) {

            int m = (r + l) / 2;

            int val = text.compare(sa[m], pt.length(), pt);

            if (val < 0) l = m;

            else r = m;

        }

        return r;

    }



    int up_bd(const string &pt) {

        int l = 1, r = n + 1;

        while (r - l > 1) {

            int m = (r + l) / 2;

            int val = text.compare(sa[m], pt.length(), pt);

            if (val <= 0) l = m;

            else r = m;

        }

        return r;

    }



    bool match(const string &pt) {

        int l = 0, r = n;

        while (r - l > 1) {

            int m = (r + l) / 2;

            int val = text.compare(sa[m], pt.length(), pt);

            if (val < 0) l = m;

            else r = m;

        }

        return text.compare(sa[r], pt.length(), pt) == 0 ? true : false;

    }



    int count(const string &pt) {

        int l_idx = low_bd(pt);

        if (l_idx == sa.size()) return 0;

        if (text.compare(sa[l_idx], pt.length(), pt) != 0) return 0;

        int r_idx = up_bd(pt);

        return r_idx - l_idx;

    }

};



