// ----- very fast input/output ----- //

int read_int() {

	char ch = getchar_unlocked();

	int res = 0;

	while('0' <= ch && ch <= '9') {

		res = res * 10 + ch - '0';

		ch = getchar_unlocked();

	}

	return res;

}

void print_str(const char* str) {

	while(*str != '\0') {

		putchar_unlocked(*str);

		++str;

	}

}

char buf[1024];

void print_int(int x) {

	if(x < 0) {

		putchar_unlocked('-');

		x *= -1;

	}

	int ptr = 0, g;

	do {

		g = x / 10;

		buf[ptr++] = x - g * 10;

		x = g;

	} while(x > 0);

	while(ptr--) {

		putchar_unlocked(buf[ptr] + '0');

	}

}

// ----- main part ----- //

int N, sep[102400], dst[102400], depth[102400], par[102400];

int inputs[307200];

void find_depth(int pos) {

	for(int i = sep[pos]; i < sep[pos + 1]; ++i) {

		depth[dst[i]] = depth[pos] + 1;

		find_depth(dst[i]);

	}

}

int main() {

	// #1. read input

	N = read_int();

	for(int i = 0; i < 3 * N - 1; ++i) {

		inputs[i] = read_int();

	}

	// #2. construct tree

	int curpos = 0;

	for(int i = 0; i < N; ++i) {

		sep[inputs[curpos] + 1] = inputs[curpos + 1];

		curpos += inputs[curpos + 1] + 2;

	}

	for(int i = 0; i < N; ++i) {

		sep[i + 1] += sep[i];

	}

