	int root = 0;

	for(int i = 0; i < N; ++i) {

		int id = inputs[curpos];

		for(int j = sep[id]; j < sep[id + 1]; ++j) {

			dst[j] = inputs[curpos + j - sep[id] + 2];

			par[dst[j]] = id;

			root ^= dst[j];

