    auto A = RD_VEC<pair<i64,i64>>(N);



    // スコアjを実現する最小コスト

    vector<i64> dp(100*N+1, INF);

    dp[0] = 0;

    for(const auto& p : A) {

        i64 v,w; tie(v,w) = p;

        // 0-1なので添字を逆順に回す

        for(i64 j = SIZE(dp)-1; j >= 0; --j) {

