class UnionFindTree

{

public:

    UnionFindTree()

    {

        for (std::size_t i = 0; i < n; i++) {

            parent[i] = i;

            rank[i] = 0;

            size[i] = 1;

        }

    }



    bool same(const std::size_t a, const std::size_t b)

    {

        return find(a) == find(b);

    }



    std::size_t find(const std::size_t a)

    {

        if (parent[a] == a) {

            return a;

        } else {

            return parent[a] = find(parent[a]);

        }

    }



    void unite(const std::size_t a_, const std::size_t b_)

    {

        const std::size_t a = find(a_);

        const std::size_t b = find(b_);

        if (a == b) {

            return;

        }

        if (rank[a] > rank[b]) {

            parent[b] = a;

            size[a] += size[b];

        } else {

            parent[a] = b;

            size[b] += size[a];

        }

        if (rank[a] == rank[b]) {

            rank[b]++;

        }

    }



    std::size_t getSize(const std::size_t a)

    {

        return size[a];

    }



private:

    std::size_t parent[n];

    std::size_t rank[n];

    std::size_t size[n];

};



