      cin >> s >> t >> x;

      seg.update(s - 1, t, x); // range add

    } else {

      int s, t;

      cin >> s >> t;

      cout << seg.query(s - 1, t).x << endl;

    }

    // seg.tour();

  }



  return 0;

}

