#include<bits/stdc++.h>

using namespace std;

typedef long long ll;



struct query{

  int type;//0=empty, 1=add-sum ,2=set-min

  ll value;

  query(int a=0,ll b=0):type(a),value(b) {}

};





#define SIZE (1<<17)



ll INF=(1LL<<60);





struct segtree{

  query s[SIZE*2];

  ll t[SIZE*2];// sum-add

  ll u[SIZE*2];// min-set



  void func(int k,int l,int r,query q){

    if(q.type==1){

      if(s[k].type==0)s[k]=q;

      else s[k].value+=q.value;

      t[k]+=q.value*(r-l);

      u[k]+=q.value;

    }

    if(q.type==2){

      s[k]=q;

      t[k]=q.value*(r-l);

      u[k]=q.value;

    }

  }



  void compute(int k,int l,int r){

