  query(int a=0,ll b=0):type(a),value(b) {}

};







ll INF=(1LL<<60);





struct segtree{

  int SIZE;

  vector<query> s;

  vector<ll> t;// sum-add

  vector<ll> u;// min-set



  segtree(int n=1){

    SIZE=1;

    while(SIZE<n)SIZE*=2;

    s.clear();

    t.clear();

    u.clear();

    s.resize(SIZE*2, query());

    t.resize(SIZE*2, 0);

    u.resize(SIZE*2, 0);

  }



  void func(int k,int l,int r,query q){

    if(q.type==1){

      if(s[k].type==0)s[k]=q;

      else s[k].value+=q.value;

      t[k]+=q.value*(r-l);

      u[k]+=q.value;

    }

    if(q.type==2){

      s[k]=q;

      t[k]=q.value*(r-l);

      u[k]=q.value;

    }

  }



