	void cueing() {

		while (get_c(), vacant())

			;

	}

	template <class T>

	auto operator>>(T &d) ->

		typename std::enable_if<std::is_signed<T>::value, customIO &>::type {

		d = 0;

		f = 0;

		cueing();

		if (c == '-')

			f = 1, get_c();

		do

			d = d * 10 + c - '0';

		while (get_c(), !vacant());

		if (f)

			d = -d;

		return *this;

	}

	template <class T>

