		scanf("%lf", &d);

		return *this;

	}

	customIO &operator>>(std::string &d) {

		d.clear();

		cueing();

		do

			d.push_back(c);

		while (get_c(), !vacant());

		return *this;

	}

	template <class T> T input() {

		T d;

		*this >> d;

		return d;

	}



	// out



	template <class T>

	auto operator<<(T d) ->

		typename std::enable_if<std::is_signed<T>::value, customIO &>::type {

		c = 0;

		f = 0;

		if (d < static_cast<T>(0))

			f = 1, d = -d;

		while (d)

			buf[c++] = d % 10 + '0', d /= 10;

		if (!c)

			buf[c++] = '0';

		if (f)

			put_c('-');

		while (c--)

			put_c(buf[c]);

		return *this;

	}

	template <class T>

	auto operator<<(T d) ->

		typename std::enable_if<!std::is_signed<T>::value, customIO &>::type {

		c = 0;

		while (d)

			buf[c++] = d % 10 + '0', d /= 10;

		if (!c)

			buf[c++] = '0';

		while (c--)

			put_c(buf[c]);

		return *this;

	}

	customIO &operator<<(char d) {

		put_c(d);

		return *this;

	}

	customIO &operator<<(double d) {

		printf("%f", d);

		return *this;

	}

	customIO &operator<<(const std::string &d) {

		for (const auto e : d)

			put_c(e);

		return *this;

	}

	customIO &operator<<(const char *d) {

		while (*d != '\0')

