const double EPS = 1e-8;



template<typename T> T chmax(T& a, const T& b){return a = (a > b ? a : b);}

template<typename T> T chmin(T& a, const T& b){return a = (a < b ? a : b);}



//有向、無向グラフ共通クラス(隣接リスト)

struct Graph {

    int n;

    using WEIGHT_TYPE = long long;

    static const WEIGHT_TYPE INF = 1e18;

    struct Edge {

        int to;

        WEIGHT_TYPE weight;

    };

    struct Edge2 {

        int from;

        int to;

        WEIGHT_TYPE weight;

    };

    vector<vector<Edge>> es;

    Graph(int n) : n(n), es(n) {}



    // dijkstra O(E log V)

    vector<WEIGHT_TYPE> dijkstra(int s) {

        vector<WEIGHT_TYPE> d(n, INF);

        d[s] = 0;

        using P = pair<WEIGHT_TYPE, int>;

        priority_queue<P, vector<P>, greater<P>> q;

        q.push({0LL, s});

        while(!q.empty()) {

            auto p = q.top();

            q.pop();

            int cur = p.second;

            auto cost = p.first;

            if(d[cur] < p.first) continue;

            for(auto &e : es[cur]) {

                int to = e.to;

                auto dist = e.weight + cost;

                if(dist < d[to]) {

                    d[to] = dist;

                    q.push({dist, to});

                }

            }

        }

        return d;

    }

    // dijkstra O(V^2)

    vector<WEIGHT_TYPE> dijkstra2(int s) {

        vector<WEIGHT_TYPE> d(n, INF);

        d[s] = 0;

        vector<int> used(n);

        auto mat = getEdgeMat();

        while(1) {

            int cur = -1;

            rep(i, n) {

                if(used[i]) continue;

                if(cur == -1 || d[i] < d[cur]) cur = i;

            }

            if(cur == -1) break;

            used[cur] = 1;

            rep(i, n) { chmin(d[i], d[cur] + mat[cur][i]); }

        }

        return d;

    }

    // warshall_floyd O(n^3)

    vector<vector<WEIGHT_TYPE>> warshall_floyd() {

        // vector<vector<WEIGHT_TYPE>> d(n, vector<WEIGHT_TYPE>(n, INF));

        // rep(i, n) d[i][i] = 0LL;

        // rep(i, n) for (auto && e : es[i]) {

        //     int j = e.to;

        //     chmin(d[i][j], e.weight);

        // }

        auto d = getEdgeMat();

        rep(k, n) rep(i, n) rep(j, n) { chmin(d[i][j], d[i][k] + d[k][j]); }

        return d;

    }

    // 頂点sから到達できるか

    vector<bool> getVisitable(int s) {

        vector<bool> ret(n);

        queue<int> q;

        q.push(s);

        ret[s] = true;

        while(!q.empty()) {

            auto cur = q.front();

            q.pop();

            for(auto &&e : es[cur]) {

                if(!ret[e.to]) {

                    ret[e.to] = true;

                    q.push(e.to);

                }

            }

        }

        return ret;

    }

    // 2部グラフ判定

    bool isBipartile() {

        vector<int> memo(n, -1);

        rep(i, n) {

            if(memo[i] != -1) continue;

            queue<int> q;

            q.push(i);

            memo[i] = 0;

            while(!q.empty()) {

                auto v = q.front();

                q.pop();

                for(auto &&e : es[v]) {

                    auto u = e.to;

                    if(memo[u] == -1) {

                        memo[u] = !memo[v];

                        q.push(u);

                    } else if(memo[u] == memo[v]) {

                        return false;

                    }

                }

            }

        }

        return true;

    }

    vector<vector<WEIGHT_TYPE>> getEdgeMat() {

        vector<vector<WEIGHT_TYPE>> mat(n, vector<WEIGHT_TYPE>(n, INF));

        rep(i, n) mat[i][i] = 0;

        rep(i, n) {

            for(auto &&e : es[i]) chmin(mat[i][e.to], e.weight);

        }

        return mat;

    }

};



