    bool unite(int x, int y){ return (x=root(x)) == (y=root(y))? false : (u[x]+=u[y], u[y]=x, true); }

};



i64 kruskal(Edges &es, int V)

{

    UnionFind uf(V);

    i64 costSum = 0;



    sort(es.begin(), es.end());

    for (const auto &e : es) {

        if (uf.unite(e.src, e.to)) costSum += e.cost;

    }



    return costSum;

}



