class LowLink {

    const int N;

    vector<vector<int>> G;

    set<int> used_v;

    vector<int> ord, low, parent;



    void dfs(int v, int &k)

    {

        used_v.insert(v);

        ord[v] = low[v] = k++;



        for (auto u : G[v]) {

            if (!used_v.count(u)) {

                parent[u] = v;

                dfs(u, k);

                low[v] = min(low[v], low[u]);

            } else if (u != parent[v]) {

                low[v] = min(low[v], ord[u]);

            }

        }

    }



    void calc_lowlink()

    {

        int k = 0;

        dfs(0, k);

    }



public:

    LowLink(int _N) : N(_N), G(_N), ord(_N), low(_N), parent(_N) {}



    vector<int> articulation_point()

    {

        vector<int> res;



        parent[0] = -1;

        calc_lowlink();



        int root_deg = 0;

        for (int i=1; i<N; i++) {

            int p = parent[i];

            if (p == 0) root_deg++;

            else if (ord[p] <= low[i]) {

                res.push_back(p);

            }

        }



        if (root_deg > 1) res.push_back(0);

        sort(res.begin(), res.end());

        res.erase(unique(res.begin(), res.end()), res.end());



        return res;

    }



    vector<PII> bridge()

    {

        vector<PII> res;

        calc_lowlink();

        for (int v=0; v<N; v++) {

            for (auto u : G[v]) {

                if (ord[v] < low[u]) {

                    res.emplace_back(min(v, u), max(v, u));

                }

            }

        }

        return res;

    }



    void add_edge(int u, int v)

    {

        G[u].push_back(v);

        G[v].push_back(u);

    }

};



