public:

	ll V;

	vector<vector<ll>> G;

	vector<vector<ll>> rG;

	vector<ll> group;

	vector<ll> List;

	vector<int> visited;

	SCC(ll V) :V(V) {

		G.resize(V); rG.resize(V);

		group.assign(V, -1);

	}



	void add_edge(ll u, ll v) {

		G[u].emplace_back(v);

		rG[v].emplace_back(u);

	}



	void dfs1(ll u) {

		visited[u] = 1;

		for (auto next : G[u]) {

			if (visited[next] == 1)continue;

			dfs1(next);

		}

		List.emplace_back(u);

	}



	void dfs2(ll u, ll group_num) {

		visited[u] = 1;

		group[u] = group_num;

		for (auto next : rG[u]) {

			if (visited[next] == 1)continue;

			dfs2(next, group_num);

		}

	}



	void solve() {

		visited.assign(V, 0);

		for (int i = 0; i < V;i++) {

			if (visited[i] == 1)continue;

			dfs1(i);

		}



		reverse(List.begin(), List.end());



		visited.assign(V, 0);

		ll group_num = 0;

		for (auto v : List) {

			if (visited[v] == 1)continue;

			dfs2(v, group_num);

			group_num++;

		}

	}



	bool same(ll u, ll v) {

