vector<int> tsort(Graph &g) {

    int n = g.size(), k = 0;

    vector<int> ord(n), in(n);

    for (int i = 0; i < n; i++) for (Edge &e : g[i]) in[e.dst]++;

    queue<int> q;

    for (int i = 0; i < n; i++) if (in[i] == 0) q.push(i);

