    int N; scanf("%d", &N);



    Graph G(N);

    for(int i=0; i<N-1; i++) {

        int s, t, w; scanf("%d%d%d", &s, &t, &w);

        G[s].push_back(Edge{t, w});

        G[t].push_back(Edge{s, w});

    }

    dfs(G, 0);

    printf("%d\n", solve(G, 0, 0));

}

