	mint& operator--() {

		if (_v == 0) _v = umod();

		_v--;

		return *this;

	}

	mint operator++(int) {

		mint result = *this;

		++*this;

		return result;

	}

	mint operator--(int) {

		mint result = *this;

		--*this;

		return result;

	}

	mint& operator+=(const mint& rhs) {

		_v += rhs._v;

		if (_v >= umod()) _v -= umod();

		return *this;

	}

	mint& operator-=(const mint& rhs) {

		_v -= rhs._v;

		if (_v >= umod()) _v += umod();

		return *this;

	}

	mint& operator*=(const mint& rhs) {

		unsigned long long z = _v;

		z *= rhs._v;

		_v = (unsigned int)(z % umod());

		return *this;

	}

	mint& operator/=(const mint& rhs) { return *this = *this * rhs.inv(); }

	mint operator+() const { return *this; }

	mint operator-() const { return mint() - *this; }

	mint pow(long long n) const {

		assert(0 <= n);

		mint x = *this, r = 1;

		while (n) {

			if (n & 1) r *= x;

			x *= x;

			n >>= 1;

		}

		return r;

	}

	mint inv() const {

		if (prime) {

			assert(_v);

			return pow(umod() - 2);

		} else {

			auto eg = internal::inv_gcd(_v, m);

			assert(eg.first == 1);

			return eg.second;

		}

	}

	friend mint operator+(const mint& lhs, const mint& rhs) {

		return mint(lhs) += rhs;

	}

	friend mint operator-(const mint& lhs, const mint& rhs) {

		return mint(lhs) -= rhs;

	}

	friend mint operator*(const mint& lhs, const mint& rhs) {

		return mint(lhs) *= rhs;

	}

	friend mint operator/(const mint& lhs, const mint& rhs) {

		return mint(lhs) /= rhs;

	}

	friend bool operator==(const mint& lhs, const mint& rhs) {

		return lhs._v == rhs._v;

	}

	friend bool operator!=(const mint& lhs, const mint& rhs) {

		return lhs._v != rhs._v;

	}

  private:

	unsigned int _v;

	static constexpr unsigned int umod() { return m; }

	static constexpr bool prime = internal::is_prime<m>;

};

template <int id> struct dynamic_modint : internal::modint_base {

	using mint = dynamic_modint;

  public:

	static int mod() { return (int)(bt.umod()); }

	static void set_mod(int m) {

		assert(1 <= m);

		bt = internal::barrett(m);

	}

	static mint raw(int v) {

		mint x;

		x._v = v;

		return x;

	}

	dynamic_modint() : _v(0) {}

	template <class T, internal::is_signed_int_t<T>* = nullptr>

	dynamic_modint(T v) {

		long long x = (long long)(v % (long long)(mod()));

		if (x < 0) x += mod();

		_v = (unsigned int)(x);

	}

	template <class T, internal::is_unsigned_int_t<T>* = nullptr>

	dynamic_modint(T v) {

		_v = (unsigned int)(v % mod());

	}

	dynamic_modint(bool v) { _v = ((unsigned int)(v) % mod()); }

	unsigned int val() const { return _v; }

	mint& operator++() {

		_v++;

		if (_v == umod()) _v = 0;

		return *this;

	}

	mint& operator--() {

		if (_v == 0) _v = umod();

		_v--;

		return *this;

	}

	mint operator++(int) {

		mint result = *this;

		++*this;

		return result;

	}

	mint operator--(int) {

		mint result = *this;

		--*this;

		return result;

	}

	mint& operator+=(const mint& rhs) {

		_v += rhs._v;

		if (_v >= umod()) _v -= umod();

		return *this;

	}

	mint& operator-=(const mint& rhs) {

		_v += mod() - rhs._v;

		if (_v >= umod()) _v -= umod();

		return *this;

	}

	mint& operator*=(const mint& rhs) {

		_v = bt.mul(_v, rhs._v);

		return *this;

	}

	mint& operator/=(const mint& rhs) { return *this = *this * rhs.inv(); }

	mint operator+() const { return *this; }

	mint operator-() const { return mint() - *this; }

	mint pow(long long n) const {

		assert(0 <= n);

		mint x = *this, r = 1;

		while (n) {

			if (n & 1) r *= x;

			x *= x;

			n >>= 1;

		}

		return r;

	}

	mint inv() const {

		auto eg = internal::inv_gcd(_v, mod());

		assert(eg.first == 1);

		return eg.second;

	}

	friend mint operator+(const mint& lhs, const mint& rhs) {

		return mint(lhs) += rhs;

	}

	friend mint operator-(const mint& lhs, const mint& rhs) {

		return mint(lhs) -= rhs;

	}

	friend mint operator*(const mint& lhs, const mint& rhs) {

		return mint(lhs) *= rhs;

	}

	friend mint operator/(const mint& lhs, const mint& rhs) {

		return mint(lhs) /= rhs;

	}

	friend bool operator==(const mint& lhs, const mint& rhs) {

		return lhs._v == rhs._v;

	}

	friend bool operator!=(const mint& lhs, const mint& rhs) {

		return lhs._v != rhs._v;

	}

  private:

	unsigned int _v;

	static internal::barrett bt;

	static unsigned int umod() { return bt.umod(); }

};

