    if(x == y) return;



    if(depth[x] < depth[y]) {

      par[x] = y;

      nGroup[y] += nGroup[x];

      nGroup[x] = 0;

    } else {

      par[y] = x;

      nGroup[x] += nGroup[y];

      nGroup[y] = 0;

      if(depth[x] == depth[y])

