// 連結成分の番号を振る関数

void dfs(int n, int comp[], vector<int> G[])

{

    int i, j, vertex, neighbor, color[N];

    stack<int> S;

    int ans[N] = {};

    // 初期状態

    for (i = 0; i < n; i++)

        color[i] = WHITE;



    for (i = 0; i < n; i++) {

