/** UnionFind木 */

class UnionFind {

  private:

	vector<int> data;



  public:

	/**

	 * @brief 初期化

	 * @param sz データサイズ

	 */

	UnionFind(int sz) : data(sz, -1) {}

	/**

	 * @brief 併合

	 * @param node1 併合する集合1のノード

	 * @param node2 併合する集合2のノード

	 * @return bool node1とnode2が同じ集合であるか

	 */

	bool unionSet(int node1, int node2) {

		node1 = root(node1);

		node2 = root(node2);

		if (node1 != node2) {

			if (data[node2] < data[node1]) swap(node1, node2);

			data[node1] += data[node2];

			data[node2] = node1;

		}

		return node1 != node2;

	}

	/**

	 * @brief 同じ集合に含まれるかを求める

	 * @param node1 検索する集合1のノード

	 * @param node2 検索する集合2のノード

	 * @return bool node1とnode2が同じ集合に含まれるか

	 */

	bool findSet(int node1, int node2) { return root(node1) == root(node2); }

	/**

	 * @brief 集合の親ノードを求める

	 * @param node 検索する集合のノード

	 * @return 集合の親ノード

	 */

	int root(int node) { return data[node] < 0 ? node : data[node] = root(data[node]); }

	/**

	 * @brief ノードが含まれる集合のサイズを求める

	 * @param node 検索するノード

	 * @return 集合のサイズ

	 */

	int size(int node) { return -data[root(node)]; }

};



