void getPrime(int sum) {

    for (int i = 2; i <= sum; i++) {

        if (!notPrime[i]) {

            prime[++total] = i;

        }

        for (int j = 1; prime[j] * i <= sum; j++) {

            notPrime[i * prime[j]] = prime[j];

            if (i % prime[j] == 0)

                break;

        }

    }

}



