void update(int u, int l, int r, int x, int v) {

    if (l == r) {

        val[u] += v;

        return;

    }

    int mid = l + r >> 1;

    if (x <= mid)

        update(u << 1, l, mid, x, v);

    else

        update(u << 1 | 1, mid + 1, r, x, v);

    val[u] = max(val[u << 1], val[u << 1 | 1]);

}

int main() {

