        a[x]++;

        update(1, 1, m, y, 1);

        G[x].push_back(y);

    }



    int ans = 0;

    for (int i = 1; i <= n; i++) {

        for (auto y : G[i]) update(1, 1, m, y, -1);

        ans = max(ans, a[i] + val[1]);

        for (auto y : G[i]) update(1, 1, m, y, 1);

    }

