  }

  if (k % moves == 0)

  {

    return score * (k / moves - 1) + ret;

  }

  ret = score = score * (k / moves), k %= moves;



  while (k > 0)

  {

    k--;

    score += C.at(next);

    ret = max(ret, score);

    next = to[next];

  }

  return ret;

