		for (int j = 1; j < 20; ++j) {

			sum[i][j] += sum[i][j - 1];

		}

	}

	for (int i = 1; i < 20; ++i) {

		for (int j = 0; j < 20; ++j) {

			sum[i][j] += sum[i - 1][j];

		}

