struct solver

{

    static constexpr i64 inf=1e17;



    struct dat

    {

        i64 x,y,pp;

    };



    struct dat2

    {

        i64 x,p;

        bool operator<(const dat2& rhs) const

        {

            return x<rhs.x;

        }

    };



    struct cht_monotone

    {

        struct line

        {

            i64 a, b;

            i64 eval(i64 x) const { return a*x+b; }

        };

        line lns[16];

        line *lp=lns,*rp=lp;

    public:

        void add(i64 a, i64 b)

        {

            while(rp>lp+1)

            {

                auto [a1,b1]=*(rp-1);

                auto [a2,b2]=*(rp-2);

                if((b-b1)*(a2-a)>(b-b2)*(a1-a)) break;

                --rp;

            }

            *rp++={a,b};

        }

        i64 get(i64 x)

        {

            assert(lp!=rp);

            while(rp>1+lp and lp->eval(x)>(lp+1)->eval(x)) lp++;

            return lp->eval(x);

        }

    };



    const int n;



    vector<i64> calc(vector<dat2> ci)

    {

        if(ci.empty()) return vector<i64>(n+1);



        sort(begin(ci), end(ci));

        const int nn=ci.size();



        i64 ps[16]={},pxs[16]={};

        for(int i=0; i<nn; i++)

        {

            ps[i]=ci[i].p;

            pxs[i]=ci[i].p*ci[i].x;

        }

        for(int i=1; i<nn; i++)

        {

            ps[i]+=ps[i-1];

            pxs[i]+=pxs[i-1];

        }



        cht_monotone cht1[16],cht2[16];

        cht1[0].add(0,0);

        cht2[0].add(0,0);

        for(int i=0; i<nn; i++)

        {

            auto [nx,np]=ci[i];

            const i64 cst1=(nx*ps[i]-pxs[i])*2;

            for(int c=0; c<=i; c++)

            {

                cht2[c+1].add(-nx, cht1[c].get(nx)+cst1);

            }

            const i64 cst2=pxs[i]*2;

            for(int c=0; c<=i+1; c++)

            {

                cht1[c].add(-ps[i], cht2[c].get(ps[i])+cst2);

            }

        }



        vector<i64> res(n+1,inf);

        for(int c=0; c<=nn; c++)

        {

            res[c]=cht2[c].get(ps[nn-1])+pxs[nn-1];

        }

        return res;

    };



    void conv(i64 (&a)[16], const vector<i64> &b)

    {

        assert((int)b.size()>n);

        for(int i=n; i>=0; i--)

        {

            a[i]+=b[0];

            for(int j=0; j<i; j++)

            {

                chmin(a[i], a[j]+b[i-j]);

            }

        }

    }



    solver() : n(read())

    {

        vector<dat> cty(n);

        for(auto& [x,y,pp]: cty) cin>>x>>y>>pp;



        vector<i64> ans(n+1,inf);



        for(int s=0; s<1<<n; s++)

        {

            vector<dat2> xctp,xctn,yctp,yctn;

            for(int i=0; i<n; i++)

            {

                auto [nx,ny,np]=cty[i];

                if(s>>i&1)

                {

                    if(nx<0) xctn.push_back({-nx,np});

                    else xctp.push_back({nx, np});

                }

                else

                {

                    if(ny<0) yctn.push_back({-ny,np});

                    else yctp.push_back({ny, np});

                }

            }



            i64 res[16]={};

            conv(res, calc(xctp));

            conv(res, calc(xctn));

            conv(res, calc(yctp));

            conv(res, calc(yctn));



            for(int i=0; i<=n; i++) chmin(ans[i], res[i]);

        }



        for(i64 x: ans) cout<<x<<endl;

    }

};

