int nextX(const bitset<sNbit> &bsX, int popX){

  bitset<sNbit> X= bsX;



  int mod= 0;

  int base_mod= 1;

  while(X.count() > 0){

    if(X.test(0)){

      mod= (mod+ base_mod) % popX;

    }



    base_mod= (2* base_mod) % popX;

    X >>= 1;

  }



  return mod;

}



int init(const bitset<Nbit> &bsX, vector<int> *base_mod, int div){

  if(div==0){ return 0; }

  else{

    const size_t N= (int)base_mod->size();



    bitset<Nbit> X= bsX;

    int mod= 0;

    base_mod->at(0)= 1 % div;

    for(size_t i=0; i<N; i++){

      if(X.test(0)){

        mod= (mod+ base_mod->at(i)) % div;

      }



      if(i+1 < N){

        base_mod->at(i+1)= (2* base_mod->at(i)) % div;

      }

      X >>= 1;

    }



    return mod;

  }

}



