      for (int j = 0; j <= d2; j++) {

        r[i + j] += p1[i] * p2[j];

      }

    }

    return r;

  };



  vector<FiniteField> f({0, 1});

  vector<FiniteField> g({1, -2, 0, 2, -1});



  vector<FiniteField> p({1});

  vector<FiniteField> q({1});

  for (int i = 0; i < 5; i++) {

    p = multiply_fn(p, f);

    q = multiply_fn(q, g);

