  for (int i = 1; i <= n; ++i) {

    int q = 1;

    for (int v : V[i])

      if (v <= i) q--;

    upd(1, 1, n, i, n, q);

  }

  int64_t ans = 0;

  for (int i = 1; i <= n; ++i) {

    ans += query(1, 1, n, i, n);

