    ll ans = 0LL;

    PrimeFact pf = PrimeFact(N);

    for(ll i=1; i<=N; i++) {

        ll temp = 1LL;

        for(auto m : pf.get(i)){

            temp *= (m.second+1);

        }

        ans += i*temp;

    }



    cout << ans << endl;

    return 0;

}

