void solve() {

  int n; cin >> n;

  vector<pii> g(n); cin >> g;



  const int num = 10;

  const int sz = 1 << num;



  vector<map<int, int>> calc(sz);

  calc[0][0] = 0;

  rep(i,num) {

    int x = 1 << i;

    for (int j = x; j < 2 * x; ++j) {

      for (auto &p : calc[j / 2]) {

        chmax(calc[j][p.first], p.second);

        chmax(calc[j][p.first + g[j-1].second], p.second + g[j-1].first);

      }

      vi erase;

      int MAX = -1;

      for (auto &p : calc[j]) {

        if (p.second <= MAX) erase.emplace_back(p.first);

        else MAX = p.second;

      }

      for (auto &v : erase) {

        calc[j].erase(v);

      }

    }

  }



  int q; cin >> q;



  while (q--) {

    int v, L; cin >> v >> L;

    vector<pii> vec(1);

    while (v >= sz) {

      int s = vec.size();

      rep(i,s) vec.emplace_back(vec[i] + g[v-1]);

      v >>= 1;

    }



    int ans = 0;

    for (auto &p : vec) {

      if (L < p.second) continue;

      auto itr = --calc[v].upper_bound(L - p.second);

      chmax(ans, itr->second + p.first);

    }

    cout << ans << '\n';

  }

}





