class Combination {

public:

	Array fact;

	Array inv;

	ll mod;

	ll mod_inv(ll x) {

		ll n = mod - 2LL;

		ll res = 1LL;

		while (n > 0) {

			if (n & 1) res = res * x % mod;

			x = x * x % mod;

			n >>= 1;

		}

		return res;

	}

	//if n >= mod use lucas 

	ll nCr(ll n, ll r) {

		if (n < r)return 0;

		if (n < mod)return ((fact[n] * inv[r] % mod) * inv[n - r]) % mod;



		ll ret = 1;

		while (n || r) {

			ll _n = n % mod, _r = r % mod;

			n /= mod; r /= mod;

			(ret *= nCr(_n, _r)) %= mod;

		}

		return ret;

	}

	ll nPr(ll n, ll r) {

		return (fact[n] * inv[n - r]) % mod;

	}

	ll nHr(ll n, ll r) {

		return nCr(r + n - 1, r);

	}

	Combination(ll _n, ll _mod) {

		mod = _mod;

		ll n = min(_n + 1, mod);

		fact.resize(n);

		fact[0] = 1;

		REP(i, n - 1) {

			fact[i + 1] = (fact[i] * (i + 1LL)) % mod;

		}

		inv.resize(n);

		inv[n - 1] = mod_inv(fact[n - 1]);

		for (int i = n - 1; i > 0; i--) {

			inv[i - 1] = inv[i] * i % mod;

		}

	}

};



