ll fac[MAX], finv[MAX], inv[MAX];





// テーブルを作る前処理

void cominit()

{

    fac[0] = fac[1] = 1;

    finv[0] = finv[1] = 1;

    inv[1] = 1;

    for (ll i = 2; i < MAX; i++)

    {

        fac[i] = fac[i - 1] * i % MOD;

        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;

        finv[i] = finv[i - 1] * inv[i] % MOD;

    }

}



// mod. m での a の逆元 a^{-1} を計算する

ll modinv(ll a, ll m)

{

    ll b = m, u = 1, v = 0;

    while (b)

    {

        ll t = a / b;

        a -= t * b;

        swap(a, b);

        u -= t * v;

        swap(u, v);

    }

    u %= m;

    if (u < 0)

        u += m;

    return u;

}



// 二項係数計算nCk,n<=10^7,k<=10^7まで

ll com(ll n, ll k)

{

    if (n < k)

