class SegmentTree{

private:

    int n; // 配列の大きさ

    int N; // 2の冪乗

    std::vector<int> data; // データを格納する配列

public:

    SegmentTree(int n = 0):n(n){

        N = 1; while(N < n) N <<= 1;

        data.assign(2 * N, 0);

    }

    void resize(int nn){

        n = nn; N = 1; while(N < n) N <<= 1;

        data.assign(2 * N, 0);

    }

     // 作用素 opで, A[idx]の値を更新

    void update(int idx, int op){

        idx += N;

        data[idx] += op;

        idx /= 2;

        while(idx > 0){

            data[idx] = data[2 * idx] + data[2 * idx + 1];

            idx /= 2;

        }

    }

    // 区間 [l, r) での値を取得

    int query(int l, int r)const{

        int res = 0;

        l += N; r += N;

        while(l < r){

            if(l & 1) res += data[l++];

            if(r & 1) res += data[--r];

            l >>= 1; r >>= 1;

        }

        return res;

    }

    int at(int idx){

        return data[idx + N];

    }

};











