  }



  for (int i = 0; i < N; i++)

    points.push_back(p[i]);



  for (auto cp : points) {

    int counter = 0;

    for (int i = 0; i < N; i++) {

      counter += isContainedCP(p[i], r / c[i], cp);

    }

    if (counter >= K) return true;

  }



  return false;

}



