constexpr int MAX = 2.01e5;



template <int N> class Mod {

  public:

  ll fact[N + 1], invfact[N + 1];

  Mod() :

      fact(), invfact() {

    fact[0] = 1;

    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;

    invfact[N] = modpow(fact[N], MOD - 2);

    for (int i = N; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;

  }

};

const Mod<MAX> mo = Mod<MAX>();

template <class S, class T> long long modnCr(const S &n, const T &k) {

  return mo.fact[n] * mo.invfact[k] % MOD * mo.invfact[n - k] % MOD;

}

template <class S, class T> long long modnPr(const S &n, const T &k) {

  return mo.fact[n] * mo.invfact[n - k] % MOD;

}



void solve(ll n, ll a, ll b) {

  long long ans = modpow(2, n) - 1;



  // ans -= modnCr(n, a);

  // ans -= modnCr(n, b);



  long long combinations_to_subtract_a = 1;



  brep(i, n - a + 1, n) {

    combinations_to_subtract_a *= i;

    combinations_to_subtract_a %= MOD;

  }



  long long combinations_to_subtract_b = combinations_to_subtract_a;



  brep(i, n - b + 1, n - a) {

    combinations_to_subtract_b *= i;

    combinations_to_subtract_b %= MOD;

  }



  combinations_to_subtract_a *= mo.invfact[a];

  combinations_to_subtract_b *= mo.invfact[b];



  ans -= combinations_to_subtract_a;

  ans -= combinations_to_subtract_b;

  ans %= MOD;

  if (ans < 0) ans += MOD;



  cout << ans << "\n";

}



