  I[0] = 1;

  for (ll i = 1; i <= r2+c2+1; i++) {

    F[i] = (F[i-1] * i) % M;

    I[i] = inv(F[i]);

  }

  for (ll i = c1; i <= c2; i++) {

    // sum(f(i+j, i)) = f(i+r2+1, i+1)

    // f(i+r2+1, i+1) = (i+r2+1)! / ((i+1)! * (r2)!)

