template <class T> std::vector<T> factorize(T n) noexcept {

  std::vector<T> ret;

  for (T p = static_cast<T>(2); p * p <= n; ++p) {

    while (n % p == static_cast<T>(0)) {

      n /= p;

      ret.push_back(p);

    }

  }

  if (n != static_cast<T>(1)) {

    ret.push_back(std::move(n));

  }

  ret.shrink_to_fit();

  return std::move(ret);

}



