constexpr std::size_t popcount32(std::uint_fast32_t c) noexcept {

#ifdef _GNUC_

  return __builtin_popcount(c);

#else

  c -= c >> 1 & 0x55555555;

  c = (c & 0x33333333) + (c >> 2 & 0x33333333);

  c = (c + (c >> 4)) & 0x0F0F0F0F;

  return c * 0x01010101 >> 24 & 0x3F;

#endif

}

