  const usize n = scan<usize>();

  auto g = md_vec(n, 0, usize());

  for (const usize i : rep(0, n - 1)) {

    const usize a = scan<usize>() - 1;

    const usize b = scan<usize>() - 1;

    g[a].push_back(b);

    g[b].push_back(a);

  }

  const usize m = scan<usize>();

  struct cons {

    usize u, v;

  };

  std::vector<cons> cs(m);

  for (auto &e : cs) {

    e.u = scan<usize>() - 1;

    e.v = scan<usize>() - 1;

  }

  const auto merge = [](auto &l, auto &r) {

    if (l.size() < r.size()) {

      std::swap(l, r);

    }

    for (const auto e : r) {

      if (l.count(e))

        l.erase(e);

      else

        l.insert(e);

    }

    r.clear();

  };

  u64 ans = 0;

  for (const usize s : rep(0, 1 << m)) {

    u64 res = 1;

    std::vector<std::set<usize>> ls(n);

    for (const usize i : rep(0, m)) {

      if (s >> i & 1) {

        ls[cs[i].u].insert(i);

        ls[cs[i].v].insert(i);

      }

    }

    make_fix([&](const auto &dfs, const usize v, const usize p) -> void {

      for (const auto e : g[v]) {

        if (e != p) {

          dfs(e, v);

          if (ls[e].empty()) {

            res *= 2;

          }

          merge(ls[v], ls[e]);

        }

      }

    })(0, n);

    if (popcount32(s) % 2 == 1)

      res = -res;

    ans += res;

  }

  std::cout << ans << std::endl;

}



