        i64 a_ = rhs.a, b = Modulus, u = 1, v = 0;

        while(b){

            i64 t = a_/b;

            a_ -= t * b; swap(a_,b);

            u -= t * v; swap(u,v);

        }

        a = a * u % Modulus;

        if(a < 0) a += Modulus;

        return *this;

    }



