    constexpr bool operator>(const modint rhs) noexcept {

        return a > rhs.a;

    }

    constexpr bool operator>=(const modint rhs) noexcept {

        return a >= rhs.a;

    }

    constexpr bool operator<(const modint rhs) noexcept {

        return a < rhs.a;

    }

    constexpr bool operator<=(const modint rhs) noexcept {

        return a <= rhs.a;

