class mint {

 private:

  ll _num,_mod=mod;

  mint set(ll num){ 

      _num = num ;

      if(_num<0){

          if(_num>=-_mod)_num=_mod+_num;

          else _num=_mod-(-_num)%_mod;

      }

      else if(_num>=_mod) _num%=_mod;

      return *this;

  }

  ll imod()const{

    ll n=_mod-2;

    ll ans = 1,x=_num;

    while(n != 0){

        if(n&1) ans = ans*x%_mod;

        x = x*x%_mod;

        n = n >> 1;

    }

    return ans;

  }

 public:

  explicit mint(){ _num = 0; }

  explicit mint(ll num){

      _num = num;

      if(_num<0){

          if(_num>=-_mod)_num=_mod+_num;

          else _num=_mod-(-_num)%_mod;

      }

      else if(_num>=_mod) _num%=_mod;

  }

