        par.resize(sz_);

        siz.assign(sz_, 1LL);

        for (ll i = 0; i < sz_; ++i) par[i] = i;

    }



    ll root(ll x) { 

        while (par[x] != x) {

            x = par[x] = par[par[x]];

        }

        return x;

