public:

    vector<int> g[200010];

    int k = 0;

    int n;

    map<pair<int, int>, int> visit;

    map<pair<int, int>, int> res;



    void dfs(int u, int pu){

        int color = 1;

        for(auto e : g[u]){

            if(visit[make_pair(e, u)]) continue;

            visit[make_pair(e, u)] = 1;

            visit[make_pair(u, e)] = 1;



            if(color == res[make_pair(u, pu)]) color++;

            res[make_pair(e, u)] = color;

            res[make_pair(u, e)] = color;

            color++;

            dfs(e, u);

        }

    }



	void solve(std::istream& in, std::ostream& out)

	{

	    in >> n;

        vector<int> a(n), b(n);

        for(int i=0; i<n-1; i++){

            in >> a[i] >> b[i];

            a[i]--; b[i]--;

            g[a[i]].push_back(b[i]);

            g[b[i]].push_back(a[i]);

