    rui2(vector<vc> &a, char key = '#') : H(sz(a)), W(sz(a[0])) {        dat.assign(H + 1, vector<T>(W + 1));        rep(h, H) { rep(w, W) { dat[h + 1][w + 1] = a[h][w] == key; }}        build();    }

