// for +

auto func2 = [](auto x, auto y) {

  return x + y;

};

auto _update2 = [](auto x, auto y) {

  return y;

};

constexpr ll unit2{0LL};



// ----- main() -----



int main()

{

  int N;

  cin >> N;

  vector<int> L(N);

  for (auto i{0}; i < N; ++i)

  {

    cin >> L[i];

  }

  SegTree<ll> tree{100010, unit2, func2, _update2};

  for (auto i{0}; i < N; ++i)

  {

    tree.update(L[i], tree.find(L[i], L[i] + 1) + 1);

  }

  ll ans{0};

  for (auto i{0}; i < N; ++i)

  {

    for (auto j{i + 1}; j < N; ++j)

    {

      int b{L[i]};

      int c{L[j]};

      ll t{tree.find(abs(b - c) + 1, b + c)};

      if (abs(b - c) < b && b < b + c)

      {

        --t;

      }

      if (abs(b - c) < c && c < b + c)

      {

        --t;

      }

      ans += t;

    }

  }

  cout << ans / 3 << endl;

}

