    if(x > y) {

      x = x - y;

    }

    else {

      y = y - x;

    }

  }



  if(x == 0) {

    return y;

  }

  else {

    return x;

  }

}



long long int approximate_sqrt(long long int x)

{

  long long int root = x/4;



  if(x <= 3) {

    return 1;

  }



  while(1) {

    root = (root + (x / root)) / 2;



    if(root * root <= x && x <= (root+1) * (root+1)) {

      return root;

    }

  }

}



int number_of_factors(long long int x)

{

  long long int root_x = approximate_sqrt(x);

  long long int x_iter = x;

  int num = 0;



  if(x == 1) {

    return 0;

  }



