using Graph = vector<vector<int> >;



// 探索

vector<bool> seen, finished;



// サイクル復元のための情報

int pos = -1; // サイクル中に含まれる頂点 pos

vector<int> hist; // 訪問履歴



void dfs(const Graph &G, int v) {

    seen[v] = true;

    hist.push_back(v);

    for (auto nv : G[v]) {

        // 完全終了した頂点はスルー

        if (finished[nv]) continue;



        // サイクルを検出

        if (seen[nv] && !finished[nv]) {

            pos = nv;

            return;

        }



        // 再帰的に探索

        dfs(G, nv);



        // サイクル検出したならば真っ直ぐに抜けていく

        if (pos != -1) return;

    }

    hist.pop_back();

    finished[v] = true;

}





