    ll l = t,r = N+1;

    while(r-l > 1){

        ll mid = (l+r)/2;

        if(ST.query(t,mid) > x)r = mid;

        else l = mid;

    }

    if(r == N+1)return N;

    return r-1;

}



ll lwb2(ll x,ll t){

    ll l = -1,r = t;

    while(r-l > 1){

        ll mid = (l+r)/2;

        if(ST.query(mid,t) > x)l = mid;

        else r = mid;

    }

    return l;

}



