    }    int pos;    void hld_build() {        never_hld = false;        if (never)precalc();        pos = 0;        vid.assign(n, -1);        head.assign(n, 0);        sub.assign(n, 1);        hvy.assign(n, -1);        hdep.assign(n, 0);        inv.assign(n, 0);        type.assign(n, 0);        build();

#ifdef _DEBUG

        cerr << "---hld_index---" << endl;        vi inds;        rep(i, n) if (sz(g[i]))inds.push_back(i);        rep(i, sz(inds)) {            str s = tos(bel(inds[i]));            cerr << std::right << std::setw(sz(s) + (i ? 1 : 0)) << inds[i];        }        cerr << endl;        rep(i, sz(inds)) { cerr << bel(inds[i]) << " "; }        cerr << endl << endl;        cerr << "---hld_edge_index---" << endl;        fora(e, edges) { if (e.f <= e.t) cerr << e.f << "-" << e.t << " " << bel(e) << endl; }        cerr << endl << endl;

#endif

    }    void build(vector<int> rs = vector<int>(1, 0)) {        int c = 0;        for (int r:rs) {            dfs(r);            bfs(r, c++);        }    }    void dfs(int rt) {        stack<P> st;        hdep[rt] = 0;        st.emplace(rt, 0);        while (!st.empty()) {            int v = st.top().first;            int &i = st.top().second;            if (i < (int) g[v].size()) {                int u = g[v][i++].t;                if (u == par[v]) continue;                hdep[u] = hdep[v] + 1;                st.emplace(u, 0);            } else {                st.pop();                int res = 0;                forg(gi, g[v]) {                    int u = t;                    if (u == par[v]) continue;                    sub[v] += sub[u];                    if (res < sub[u]) res = sub[u], hvy[v] = u;                }            }        }    }    void bfs(int r, int c) {        int &k = pos;        queue<int> q({r});        while (!q.empty()) {            int h = q.front();            q.pop();            for (int i = h; i != -1; i = hvy[i]) {                type[i] = c;                vid[i] = k++;                inv[vid[i]] = i;                head[i] = h;                forg(gi, g[i])if (t != par[i] && t != hvy[i]) q.push(t);            }        }    }    vi vid;public:    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;    vector<int> disv;    vector<signed> dep, par;    vector<int> head, sub, hvy, inv, type, hdep/*おそらくグループ内のdep*/;/*vid := bel()*/    int root;    tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }    int lca(int a, int b) {        if (never)precalc();        int x = in[a];        int y = in[b];        if (x > y) { swap(x, y); }        int pos = rmq.query(x, y + 1);        return id[pos];    }    int dis(int a, int b) {        if (never)precalc();        int x = in[a];        int y = in[b];        if (x > y) { swap(x, y); }        int pos = rmq.query(x, y + 1);        int p = id[pos];        return disv[a] + disv[b] - disv[p] * 2;    }    void for_each_l/*O(N) 頂点に対しての処理順が可換*/(int u, int v, function<void(int)> fnode) {        int r = lca(u, v);        while (u != r) {            fnode(u);            u = par[u];        }        while (v != r) {            fnode(v);            v = par[v];        }        fnode(r);    }    void for_each_edge_l/*O(N) 頂点に対しての処理順が可換*/(int u, int v, function<void(edge<int> &)> fedge) {        int r = lca(u, v);        auto sub = [&](int u, int r) {            while (u != r) {                forg(gi, g[u]) {                    if (t == par[u]) {                        fedge(g[u][gi]);                        u = par[u];                        break;                    }                }            }        };        sub(u, r);        sub(v, r);    }    void for_each_/*[l,r) O(log(N))*/   (int u, int v, const function<void(int, int)> &f) {        if (never_hld)hld_build();        while (1) {            if (vid[u] > vid[v]) swap(u, v);            int l = max(vid[head[v]], vid[u]);            int r = vid[v] + 1;            f(l, r);            if (head[u] != head[v]) v = par[head[v]]; else break;        }    }    void for_each_edge/*[l,r) O(log(N)) 辺を頂点として扱っている 上と同じ感じで使える*/(int u, int v, const function<void(int, int)> &f) {        if (never_hld)hld_build();        while (1) {            if (vid[u] > vid[v]) swap(u, v);            if (head[u] != head[v]) {                int l = vid[head[v]];                int r = vid[v] + 1;                f(l, r);                v = par[head[v]];            } else {                if (u != v) {                    int l = vid[u] + 1;                    int r = vid[v] + 1;                    f(l, r);                }                break;            }        }    }    int bel(int v) {        /*hld内での頂点番号を返す*/        if (never_hld)hld_build();        return vid[v];    }    int bel(int f, int t) {        /*辺のクエリを扱うときどの頂点に持たせればいいか(vidを返すのでそのままupd出来る)*/        if (never_hld)hld_build();        return hdep[f] > hdep[t] ? vid[f] : vid[t];    }    int bel(edge<T> &e) {        /*辺のクエリを扱うときどの頂点に持たせればいいか(vidを返すのでそのままupd出来る)*/        if (never_hld)hld_build();        return hdep[e.f] > hdep[e.t] ? vid[e.f] : vid[e.t];    }    template<class ... U> int operator()(U ... args) { return bel(args...); }};;

