template<class T=int> class digrid_k6 : public digraph<T> {

public:

    using digraph<T>::g;    using digraph<T>::n;    using digraph<T>::edges;

    int H, W;

    void add(int f, int t, T c = 1) {

        if (!(0 <= f && f < n && 0 <= t && t < n)) {            debugline("digrid_k6 add");            deb(f, t, c);            ole();        }

