template<class T> int longest_path(digraph<T> &g) {    vi top;    if (!topo(top, g)) { return linf; }    int n = sz(top);    vi dp(n, 0);    for (auto &&i : top) { forg(gi, g[i]) { forg_init(g[i]);chma(dp[t], dp[i] + 1); }}    return max(dp);}

