// 汎用的な二分探索のテンプレ

int binary_search(int key, int size) {

    int ng = -1;

    int ok = size;



    /* ok と ng のどちらが大きいかわからないことを考慮 */

    while (abs(ok - ng) > 1) {

        int mid = (ok + ng) / 2;



        if (isOK(mid, key)) ok = mid;

        else ng = mid;

    }

    return ok;

}



