{

    int n, m;

    scanf( "%d%d", &n, &m );

    pre();

    for( int i = 1; i <= m; i++ )

    {

        int u, v;

        scanf("%d%d", &u, &v);

        add(u, v);

        add(v, u);

    }

    if(m&1){

        printf("-1\n");

        return 0;

    }

