    {

        if(du[i]){

            last.push_back(i);

        }

    }

    memset(du, 0, sizeof(du));

    memset(vis, 0, sizeof(vis));

    int l = last.size();

    for(int i=0; i < l / 2; i++)

    {

        change(last[i], last[l-1-i]);

    }

    dfsans(1, 1);

    for(int i=0; i<top; i++)

    {

        printf("%d %d\n", ansx[i], ansy[i]);

    }

    //printf("%d\n", top);

    return 0;

}

