  }

  int dfs(int pos, int p, int q, int mxp, int mxq) {

    if (mxp < pos || mxq < pos) return 0;

    if (pos == n) return 1;

    p = min(p, k / 2 + 1);

    q = min(q, k / 2 + 1);

    long long enc = encode(p, q, mxp, mxq);

