ll pow_mod(ll x, ll y, ll mod)

{

	ll ans=1;

	for(;y>0;y>>=1){

		if(y&1)(ans*=x)%=mod;

		(x*=x)%=mod;

	}

	return ans;

}



ll n, m;

ll s , t;

int d[300000];



vector<int> vv[300000];



void dijkstra(int s)

{

	priority_queue<P, vector<P>, greater<P>> que;

	fill(d, d + 3 * n, INF);

	d[s] = 0;

	que.push(P(0, s));



	while (!que.empty())

	{

		P p = que.top();

		que.pop();

		int v = p.second;

		if(d[v]<p.first){

			continue;

		}

		for (int i = 0; i < vv[v].size();i++){

			int u = vv[v][i];

			if(d[u]>d[v]+1){

				d[u] = d[v] + 1;

				que.push(P(d[u], u));

			}

		}

	}

}



