const int MAX_N = 2000000;

ll inv[MAX_N + 10];

ll fac[MAX_N + 10], facInv[MAX_N + 10];

class MATH{

public:

    MATH(){

        inverse();

        factroial();

    }

    ll nCk(ll n, ll k){// n! / k!*(n-k)!

        if(k < 0 || k > n) return 0;

        ll ret = fac[n];

        (ret *= facInv[k]) %= mod;

        (ret *= facInv[n - k]) %= mod;

        return ret;

    }

    ll nHk(ll n, ll k){// nHk = n+k-1 C k = (n+k-1)! / k! * (n-1)!

        if(n == 0 && k == 0) return 1;

        ll ret = fac[n + k - 1];

        (ret *= facInv[k]) %= mod;

        (ret *= facInv[n - 1]) %= mod;

        return ret;

    }

    ll nPk(ll n, ll k){//nPk = n! / (n-k)!

        if(k < 0 || k > n) return 0;

        ll ret = fac[n];

        (ret *= facInv[n - k]) %= mod;

        return ret;

    }

private:

    void inverse(void){

        inv[1] = 1;

        for (int i = 2; i <= MAX_N; ++i){

            // inv[i] = mod - (mod / i) * inv[mod % i] % mod;

            inv[i] = inv[mod % i] * (mod - mod / i) % mod;

        }

    }

    void factroial(void){

        fac[0] = facInv[0] = 1;

        for (int i = 1; i <= MAX_N; ++i){

            fac[i] = (fac[i - 1] * i) % mod;

            facInv[i] = (facInv[i - 1] * inv[i]) % mod;

        }

    }

};



