//lld でなくdoubleではどうか

template<class F> dou golddd(dou left, dou right, F calc) {

    dou GRATIO = 1.6180339887498948482045868343656;

    dou lm = left + ((right - left) / (GRATIO + 1.0));

    dou rm = lm + ((right - lm) / (GRATIO + 1.0));

    dou fl = calc(lm);

    dou fr = calc(rm);

    //200にすればおそらく大丈夫

    //余裕なら300に

    int k = 141;

    while (--k) {

        if (fl < fr) {

            right = rm;

            rm = lm;

            fr = fl;

            lm = left + ((right - left) / (GRATIO + 1.0));

            fl = calc(lm);

        } else {

            left = lm;

            lm = rm;

            fl = fr;

            rm = lm + ((right - lm) / (GRATIO + 1.0));

            fr = calc(rm);

        }

    }

    return left;

}

template<class F> dou golddd_s(dou l, dou r, F calc, int time = 2000) {

    clock_t lim = time;

    dou mini = 0, minv = MAX(dou);

    //区間をk分割する

    rep(k, 1, inf) {

        clock_t s = clock();

        dou haba = (r - l) / k;

        dou nl = l;

        dou nr = l + haba;

        rep(i, k) {

            dou ni = golddd(nl, nr, calc);

            if (chmi(minv, calc(ni))) mini = ni;

            nl = nr;

            nr = nl + haba;

        }

        clock_t now = clock();

        clock_t dif = now - s;

        if (now + dif * 2 >= lim)break;

    }

    return mini;

}





