    Node(int xx, int yy): x(xx), y(yy){}

};

vector<Node> ans;

bool vis[maxn];

int main(){

    scanf("%d", &n);

    int da = 0, xiao = 0;

    for(int i = 1; i <= n; i++){

        scanf("%d", &a[i]);

        if(a[i] >= 0) da++;

        else

            xiao++;

    }

    if(!xiao){

        sort(a + 1, a + 1 + n);

        int p = a[1];

        for(int i = 2; i <= n - 1; i++){

            ans.push_back(Node(p, a[i]));

            p -= a[i];

        }

        ans.push_back(Node(a[n], p));

        printf("%d\n", a[n] - p);

    }

    else if(!da){

        sort(a + 1, a + 1 + n);

        int p = a[n];

        for(int i = n - 1; i >= 2; i--){

            ans.push_back(Node(p, a[i]));

            p -= a[i];

        }

        ans.push_back(Node(p, a[1]));

        printf("%d\n", p - a[1]);

    }

    else{

        int fu = INF, z = INF;

        sort(a + 1, a + 1 + n);

