    while ( s != tmpu ) { //find minflow

        minflow = min( minflow, Edge[pre[tmpu]].cap - Edge[pre[tmpu]].flow );

        tmpu = Edge[pre[tmpu]].from;

    }



    Maxflow += minflow;

    COST += minflow * d[t];



    while ( s != t ) {

        Edge[pre[t]].flow += minflow;

        Edge[pre[t] ^ 1].flow -= minflow;

        t = Edge[pre[t]].from;

    }

}



