    } else {

      if (t[root*2] <= maxc) {

        update(2*root+1, pos, maxc-t[root*2], m+1, r);

        t[root*2] = 0;

      } else {

        update(2*root, pos, maxc, l, m);

      }

    }

    t[root] = t[root*2] + t[root*2+1];

  }



