	inline void addedge(ri x,ri y){

		nxt[++tot]=head[x];

		adj[head[x]=tot]=y;

	}

	inline void dfs(ri x){

		sz[x]=1;

		p[x][x]=q[x][x]=1;

		for(ri y,i=head[x];i;i=nxt[i])

			if((y=adj[i])!=f[x])

				p[y]=p[x],

				f[y]=x,

				dep[y]=dep[x]+1,

				dfs(y),

				q[x]|=q[y],

				sz[x]+=sz[y],

				son[x]=sz[y]>sz[son[x]]?y:son[x];

	}

	inline void dfs2(ri x,ri tp){

		top[x]=tp;

		if(son[x])

			dfs2(son[x],tp);

		for(ri y,i=head[x];i;i=nxt[i])

			if((y=adj[i])!=f[x]&&y!=son[x])

				dfs2(y,y);

	}

	inline int lca(ri x,ri y){

		while(top[x]^top[y])

			if(dep[top[x]]>dep[top[y]])

				x=f[top[x]];

			else

				y=f[top[y]];

		return dep[x]<dep[y]?x:y; 

	}

	inline int sec(ri x,ri y){ // lca(x,y) = x

		while(top[x]^top[y]){

			if(f[top[y]]==x) return top[y];

			y=f[top[y]];

		}

		return son[x];

	}

	inline bit S(ri a,ri b){

		ri x=lca(a,b);

		bit ans=p[a]^p[b];

		ans[x]=1;

		if(x!=b)

			ans|=q[b];

		else

			ans|=~q[sec(b,a)];

		if(x!=a)

			ans|=q[a];

		else

			ans|=~q[sec(a,b)]; 

		return ans;

	}

}t;

