//        return a != r.a ? a < r.a : b != r.b ? b < r.b : c != r.c ? c < r.c : d < r.d;

    }

    bool operator==(const F &r) const {

        return a == r.a && b == r.b && c == r.c && d == r.d;

    }

    bool operator!=(const F &r) const {

        return a != r.a || b != r.b || c != r.c || d != r.d;

    }

    int operator[](int i) {

        assert(i < 4);

        return i == 0 ? a : i == 1 ? b : i == 2 ? c : d;

