void compress(vi &a) {

    vi b;

    int len = a.size();

    for (int i = 0; i < len; ++i) {

        b.push_back(a[i]);

    }

    sort(b);

    UNIQUE(b);

    for (int i = 0; i < len; ++i) {

        a[i] = lower_bound(all(b), a[i]) - b.begin();

    }

}



