int time_nanbai(int milli) {

    auto dec = duration_cast<nanoseconds>(past_time - start_time);

    auto part = calc_time_nano();

    auto can_time = nanoseconds(milli * 1000 * 1000);

    can_time -= part;

    can_time -= dec;

    return div(can_time, part);

}



