#include <stdio.h>

#include <vector>

#include <algorithm>

#include <map>



using namespace std;



struct node {

    node *l = nullptr;

    node *r = nullptr;

    node *p = nullptr;

    long long val = 0;

    long long sum = 0;

    node() {}

};



void fix(node *x) {

    x->sum = x->val;

    if (x->l) x->sum += x->l->sum;

    if (x->r) x->sum += x->r->sum;

}



void rot(node *x) {

    node *y = x->p, *z = y->p;

    if (z) {

        if (y == z->l) z->l = x;

        if (y == z->r) z->r = x;

    }

    x->p = z; y->p = x;

    if (x == y->l) {

        y->l = x->r; x->r = y;

        if (y->l) y->l->p = y;

    } else {

        y->r = x->l; x->l = y;

        if (y->r) y->r->p = y;

    }

    fix(y);

}



node *splay(node *x) { while (x->p) { node *y = x->p, *z = y->p;

        if (z) rot((x == y->l) == (y == z->l) ? y : x);

        rot(x);

    }

    fix(x);

    return x;

}



void join(node *x, node *y) {

    if (!x || !y) return;

    splay(x);

    while (x->r) x = x->r;

    splay(x);

    splay(y);

    x->r = y;

    y->p = x;

}



node *split_left(node *x) {

    splay(x);

    node *y = x->l;

    if (y) y->p = x->l = nullptr;

    return y;

}



node *split_right(node *x) {

    splay(x);

    node *y = x->r;

    if (y) y->p = x->r = nullptr;

    return y;

}



void rotate(node *x) {

    join(x, split_left(x));

}





pair<node *, node *> link(node *u, node *v) {

    node *uv = new node();

    node *vu = new node();

    rotate(u);

    rotate(v);

    join(u, uv);

    join(uv, v);

    join(v, vu);

    return { uv, vu };

}



void cut(pair<node *, node *> e) {

    rotate(e.first);

    split_right(e.first);

    split_left(e.second);

    split_right(e.second);

    delete e.first;

    delete e.second;

}



