		tr[x].rc=bt(mid+1,r);

		tr[x].c=update(tr[tr[x].lc].c,tr[tr[x].rc].c);

	}

	else tr[x].c=node(l*d+a[l],-l*d+a[l],l,l);

	return x;

}

