	}



	void update(int l, int r, int ql, int qr, ll val, int node) {

		if (ql > qr) return;

		if (ql > r || qr < l) return;

		if (ql <= l && qr >= r) {

			add(tree, node, val);

			add(lazy, node, val);

			return;

		}

		lz(node);

		int mid = l + (r - l) / 2;

		update(l, mid, ql, qr, val, 2 * node);

		update(mid + 1, r, ql, qr, val, 2 * node + 1);

		tree[node] = max(tree[2 * node], tree[2 * node + 1]);

	}



	ll query(int l, int r, int ql, int qr, int node) {

		if (ql > qr) return -1e18;

		if (ql > r || qr < l) return -1e18;

		if (ql <= l && qr >= r) return tree[node];

		lz(node);

		int mid = l + (r - l) / 2;

		return max(query(l, mid, ql, qr, 2 * node), query(mid + 1, r, ql, qr, 2 * node + 1));

	}



};



const ll INF = 1e18;



class TaskW {

public:

	void solve(std::istream& in, std::ostream& out) {

		int N, M;

		in >> N >> M;

		vector<int> ls(M), rs(M);

		vector<ll> a(M), dp(N + 1, -INF);

		vector<vector<int>> st(N + 1), en(N + 1);

		for (int i = 0; i < M; i++) {

			in >> ls[i] >> rs[i] >> a[i];

			st[ls[i]].push_back(i);

			en[rs[i]].push_back(i);

		}

		dp[0] = 0;

		segtreelz root = segtreelz(4 * N + 5);

		for (int i = 1; i <= N; i++) {

			for (int idx : st[i]) {

				root.update(0, N, 0, i - 1, a[idx], 1);

			}

			dp[i] = root.query(0, N, 0, i - 1, 1);

			root.update(0, N, i, i, dp[i], 1);

			for (int idx : en[i]) {

				root.update(0, N, 0, ls[idx] - 1, -a[idx], 1);

			}

		}

		out << vec_max(dp);

	}

};



