#include <bits/stdc++.h>

using namespace std;

const int MAXN=200100,MAXM=1000100,INF=0x3f3f3f3f;

struct Edge

{

	int to,val,nxt;

	inline Edge() {}

	inline Edge(register int to,register int val,register int nxt):to(to),val(val),nxt(nxt) {}

};

Edge e[MAXM];

int head[MAXN],S,T,cnt=-1;

int d[MAXN],cur[MAXN];

int vis1[MAXN],vis2[MAXN],id[MAXN],nxt[MAXN];

int N;

queue<int> q,q_;

vector<int> bel[MAXN];

inline void Addedge(register int x,register int y,register int z)

{

	e[++cnt]=Edge(y,z,head[x]),head[x]=cnt;

	e[++cnt]=Edge(x,0,head[y]),head[y]=cnt;

	return;

}

inline bool bfs()

{

	while(!q.empty()) q.pop();

	memset(d,-1,sizeof(d));

	d[S]=0,cur[S]=head[S],q.push(S);

	while(!q.empty())

	{

		register int now=q.front(); q.pop();

		for(register int i=head[now];~i;i=e[i].nxt)

			if(e[i].val&&(!(~d[e[i].to])))

			{

				register int to=e[i].to;

				d[to]=d[now]+1,cur[to]=head[to];

				if(to==T) return 1;

				q.push(to);

			}

	}

	return 0;

}

inline int dfs(register int now,register int num)

{

	if(now==T||!num) return num;

	register int ans=0;

	for(register int &i=cur[now];~i;i=e[i].nxt)

		if(e[i].val&&d[e[i].to]==d[now]+1)

		{

			register int to=e[i].to;

			register int f=dfs(to,min(num,e[i].val));

			if(f)

			{

				e[i].val-=f,e[i^1].val+=f;

				ans+=f,num-=f;

				if(!num) break;

			}

		}

	return ans;

}

inline int maxflow()

{

	register int ans=0;

	while(bfs()) ans+=dfs(S,INF);

	return ans;

}

inline bool solve(register int n)

{

	for(register int i=1;i<n;i++)

		for(register int j=head[n+i];~j;j=e[j].nxt)

			if(e[j].to&&!e[j].val) id[i]=e[j].to,vis1[e[j].to]=1;

	for(register int i=1;i<=n;i++)

		if(!vis1[i]) q_.push(i);

	register int cnt_=0;

	while(!q_.empty())

	{

		register int now=q_.front(); q_.pop();

		cnt_++;

		for(register int i=0;i<(int)bel[now].size();i++)

			if(!vis2[bel[now][i]])

			{

				register int to=bel[now][i];

				vis2[to]=1,nxt[to]=now,q_.push(id[to]);

			}

	}

	return cnt_==n;

}

int main()

{

	ios::sync_with_stdio(false),cin.tie(0),cout.tie(0);

	memset(head,-1,sizeof(head));

	cin>>N;

	S=0,T=N<<1;

	for(register int i=1,x,y;i<N;i++)

	{

		cin>>x;

		Addedge(S,N+i,1);

		for(register int j=1;j<=x;j++) cin>>y,Addedge(N+i,y,1),bel[y].push_back(i);

	}

	for(register int i=1;i<=N;i++) Addedge(i,T,1);

	if(maxflow()<N-1) return puts("-1"),0;

	if(!solve(N)) return puts("-1"),0;

	for(register int i=1;i<N;i++) cout<<id[i]<<" "<<nxt[i]<<"\n";

	cout<<endl;

	return 0;

}

