            int xf = x + dx[dir] * chg, yf = y + dy[dir] * chg;

            if(abs(xf) + abs(yf) < (1LL << (cur - 1)) ) {

                putchar(dr[dir]);

                dfs(xf, yf, cur - 1);

                break;

            }

        }

    }

    inline void solve() {

        rep(i, n) ham = max(ham, x[i] + y[i]) + 2;

        for(k = 0; (1LL << k) < ham; ++k) ;

        if(even) printf("%lld\n1 ", ++k + 1);

        else printf("%lld\n", ++k);

        for(int i = k; i ; --i) {

            a[i] = 1LL << (i - 1);

            printf("%lld%c", a[i], i == 1LL ? '\n' : ' ');

        }

        for(int i = 1; i <= n; ++i){

            if(even) putchar('L'), x[i]++;

            dfs(x[i], y[i], k);

            putchar('\n');

