        v[j].emplace_back(p.second, p.first);

      std::sort(v[j].begin(), v[j].end(), std::greater<>());

    }

  }



  // 偶奇で分けたとき，各々のうちで最も多く出現する値とその数（へのイテレータ）

  // *f0 の型は std::pair<int, int> のはず

  auto f0=v[0].begin();

  auto f1=v[1].begin();



  if (v[0].size() == 1 && v[1].size() == 1) {

    // 各グループの種類数がどちらも 1 のとき

