}



int HowMany(vector <int> A, int K, int N){

  if (N == K)

    return 1;

  int i = 0;

  int x = N - MinIndex(A), y = MinIndex(A);

  while (x > 0){

    i++;

    x -= K;

    x++;

  }

  while (y > 0){

    i++;

    y -= K;

    y++;

  }

  return i-1;

}



