	ll q_pow(ll a,ll b)

	{

		ll ans=1;

		a=a%mod;

		while(b)

		{

			if(b&1)

				ans=ans*a%mod;

			a=a*a%mod;

			b>>=1;

		}

		return ans%mod;

	}

	ll getreverse(ll x)

	{

		return q_pow(x,(ll)(mod-2))%mod;

	} 

	ll sum(ll p,ll k,ll b)

	{  

	    ll tm = (q_pow(p,k*b+(ll)1)-(ll)1)%mod;

	    ll reverse = getreverse(p-(ll)1)%mod;

	    return tm*reverse%mod;

	}



