void dfs(int u, int p, int& res, int& pos) {

  f[u][0] = f[u][1] = 1;

  g[u][0] = g[u][1] = 0;

  for (int i = 0; i < e[u].size(); ++i) {

    int v = e[u][i];

    if (v == p) continue;

    dfs(v, u, res, pos);

    if (f[u][0] < f[v][0] + 1) {

      f[u][1] = f[u][0];

      g[u][1] = g[u][0];

      f[u][0] = f[v][0] + 1;

      g[u][0] = v;

    } else if (f[u][1] < f[v][0] + 1) {

      f[u][1] = f[v][0] + 1;

      g[u][1] = v;

    }

  }

  if (res < f[u][0] + f[u][1]) {

    res = f[u][0] + f[u][1] - 1;

    pos = u;

  }

}



vector<int> sol(int m, int a[]) {

  vector<int> r;

  int beg = 1;

  for (int i = 0; i < m; ++i) {

    int end = beg + a[i] - 1;



    for (int j = beg + 1; j <= end; ++j) r.push_back(j);

    r.push_back(beg);



    beg = end + 1;

  }

  return r;

}



int cmp(vector<int>& a, vector<int>& b) {

  for (int i = 0; i < a.size(); ++i) {

    if (a[i] != b[i]) return a[i] - b[i];

  }

  return 0;

}



