      v[x][y] = 1;

      if(u[x][y + 1] == u[x][y] && !v[x][y + 1] && y + 1 <= m)

            dfs(x, y + 1);

      if(u[x][y - 1] == u[x][y] && !v[x][y - 1] && y - 1 >= 1)

            dfs(x, y - 1);

      if(u[x + 1][y] == u[x][y] && !v[x + 1][y] && x + 1 <= n)

            dfs(x + 1, y);

      if(u[x - 1][y] == u[x][y] && !v[x - 1][y] && x - 1 >= 1)

            dfs(x - 1, y);

}



