int find_set(int v) {

    if (v == p[v]) {

        return v;

    }

    return p[v] = find_set(p[v]);

}



bool union_set(int v1, int v2) {

    v1 = find_set(v1);

    v2 = find_set(v2);

    if (v1 == v2) {

        return false;

    }

    p[v1] = v2;

    return true;

}



int get_max(int v, int fin, int mx, int p) {

    if (v == fin) {

        return mx;

    }

    int res = -1;

    for (int i = 0; i < g[v].size(); ++i) {

        const int to = g[v][i], c = d[v][i];

        if (to == p) {

            continue;

        }

        res = max(res, get_max(to, fin, max(mx, c), v));

    }

    return res;

}



