const ll inf=1e9+7;



ll mult(ll n,ll m){//n^m%infを求める

    if(m==1){

        return n%inf;

    }else if(m%2==0){//オーバーフロー防止のためにn^(m/2)*n^(m/2)を考える

        ll t=mult(n,m/2);

        return (t*t)%inf;

    }else{//奇数の時はn^(m-1)*nを考える

        ll t=mult(n,m-1);

        return (t*n)%inf;

    }

}



