void Dijkstra(int s, ll dis[N], int dp[N]) {

	for (int i = 1; i < N; i++) dis[i] = INF;

	dis[s] = 0;

	dp[s] = 1;

	set< pair<ll, int> > st; st.insert(make_pair(0, s));

	while (!st.empty()) {

		int v = st.begin()->second;

		st.erase(st.begin());

		for (pii e : G[v]) {

			int u = e.first, w = e.second;

			if (dis[v] + w < dis[u]) {

