    ll a = 1, p = x;

    while(e > 0) {

      if(e%2 == 0) {p = (p*p) % MOD; e /= 2;}

      else {a = (a*p) % MOD; e--;}

    }

    a %= MOD;

    return ModInt(a);

  }

