		if(a > 1 && a - 1 != b)

			can.push_back(a - 1);

		if(a + 1 < n && a + 1 != b)

			can.push_back(a + 1);

		for(int i = 0; i < can.size() && !ret; ++i)

			ret |= calc(can[i], b, !t);

	}

	return ret;

}



