#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops,fast-math")

#define kill(x) return cout<<x<<'\n', 0;

using namespace std;

const int N=2e5+100;

vector <int> g[N];

ll dp[N];

ll p1=0;

ll z=0;

void dfs(ll v,ll p,ll k){

    multiset <int> s;

    for (auto u : g[v]){

        if (u==p) continue;

        dfs(u,v,k);

        s.insert(dp[u]+1);

        if (dp[u]+1>k){

            p1=1;

            return ;

        }

    }

    if (p1) return ;

   // if (v==1) cout << s.size() << " end " << endl;

   vector <int> y;

    while(s.size()>1){

        auto t=s.end();

        t--;

        ll val1=*t;

        s.erase(t);

        if (*s.begin()+val1>k){



                y.pb(val1);

                continue;

        }

        t=s.upper_bound(k-val1);

        t--;

        s.erase(t);

        z++;

    }

    if (s.size()){

        y.pb(*s.begin());

    }

    if (y.size()>2){

        p1=1;

        return ;

    }

    if (y.size()){

        sort(y.begin(),y.end());

        for (int i=1;i<y.size();i++) z++;

        dp[v]=y[0];

        if (v==1) z++;

    }

    if (dp[1]>k) p1=1;

}

int32_t main(){

    sync;

    ll n;

    cin >> n;

    for (int i=1;i<n;i++){

        ll u,v;

        cin >> u >> v;

        g[u].pb(v);

        g[v].pb(u);

    }

    ll l=0,r=n+10;

    dfs(1,1,r);

    ll o=z;

    while(r-l>1){

        memset(dp,0,sizeof dp);

        p1=0;

        ll mid=(r+l)/2;

        z=0;

        dfs(1,1,mid);

        if (!p1 && z==o) r=mid;

        else l=mid;

        //cout << z << " f " << mid << endl;

    }memset(dp,0,sizeof dp);

    z=0;

    p1=0;

    dfs(1,1,r);

    cout << z << " " << r << endl;

}

