#define MAX_N 8003



bool can(vector <int> v ,int x){

    bitset <MAX_N> bs; bs[0] = 1;

    int tot = 0;

    for(int&i : v)

        bs |= (bs<<i) ,tot += i;

    return !((tot+x)&1) && (tot >= x && bs[(tot-x)/2]);

}



