        min_idx = i;

    }

    if (min_idx == -1)

      break;

    Program p = q[min_idx].top(); q[min_idx].pop();

    if (tv.empty())

      tv.emplace(p.t, p.c);

    else {

      if (tv.top().first < p.s || tv.top().first <= p.s && tv.top().second == p.c) {

        tv.pop();

