using namespace std;



struct segtree

{

	vector<int> t;

	segtree(int n) :t(n * 2 - 1, 0) {}

	void add(int a, int b, int o, int l, int r)

	{

		if (a >= r || b <= l)

			return;

		if (a <= l && b >= r) {

			t[o]++;

			return;

		}

		int m = (l + r) / 2;

		add(a, b, o + 1, l, m);

		add(a, b, o + (m - l) * 2, m, r);

	}

	int min(int o, int l, int r)

	{

		if (l + 1 == r)

			return t[o];

		int m = (l + r) / 2;

		int p = min(o + 1, l, m);

		int q = min(o + (m - l) * 2, m, r);

		return max(p, q) + t[o];

	}

};



