        if (visited[i]) cnt1++;

    }

    dfs(1);

    for (int i = 0; i < n; i++) {

        if (visited[i]) cnt2++;

    }

    cnt2 -= cnt1;

    int rem = n - (cnt1 + cnt2);

    (cnt1 >= cnt2 ? cnt1 : cnt2) += rem;

    long long es = 1ll * cnt1 * (cnt1 - 1) / 2 + 1ll * cnt2 * (cnt2 - 1) / 2;

    cout << es - m << endl;

