//	set<ll> st;

//	map<ll,ll> mp;

//	rep(i,N) st.insert(x[i]);

//	for(auto t: st) mp[t] = mp.size();



	RMQ<ll> sg(200005);

	ll sum = 0;

	sg.update(0,0);

	rep(i,N){

		sum += s[i];

		ll mn  = sg.get(0,i+1);

		chmax(ans, sum - mn);

		ll d = x[i+1] - x[i];

		sum -= d;

		sg.update(i+1, sum);

	}



	cout << ans << endl;



	return 0;

}

