    vector<pair<ll, char>> parts(N * 3);

    for (int i = 0; i < 3; ++i) {

        for (int j = 0; j < N; ++j) {

            cin >> parts[i * N + j].first;

            parts[i * N + j].second = s[i];

        }

    }

    sort(parts.begin(), parts.end(), cmp);

