ll d[MAX_V];

void solve() {

    d[0] = 0;

    queue<pli> q;

    q.push(pli(0LL, 0));

    while (!q.empty()) {

        pli p = q.front(); q.pop();

        int v = p.second;

        for (size_t i = 0U; i < g[v].size(); ++i) {

            Edge e = g[v][i];

            if (d[e.to] > e.cost + d[v]) {

                d[e.to] = e.cost + d[v];

                q.push(pli(d[e.to], e.to));

            }

        }

    }

}

