    int k; cin >> k;

    for (int i = 0; i <= k; ++i) {

        d[i] = INF;

    }

    for (int i = 0; i < k; ++i) {

        Edge e = { i + 1, 1LL };

        g[i].push_back(e);

    }

    for (int i = 1; i < k; ++i) {

        Edge e = { i * 10 % k, 0LL };

        if (e.to == 0) e.to = k;

        g[i].push_back(e);

    }

    solve();

    cout << d[k] << endl;

    return 0;

}

