P knapsack(int y){

    int dp[x[y] + 1] = {};

    rep(i, v[y].size()){

        if(i == 0){

            if(v[y][i].first <= x[y]){

                dp[v[y][i].first] = 1;

            }

            if(v[y][i].second <= x[y]){

                dp[v[y][i].second] = 1;

            }

        }else{

            int tmp[x[y] + 1] = {};

            rep(j,x[y] + 1){

