	cin.tie(0);

	ios_base::sync_with_stdio(false);



	cin >> N >> M >> R;

	VI r(R);

	FOR(i, 0, R) {

		cin >> r[i];

		r[i]--;

	}



	VI a(M), c(M), b(M);

	VVL dist(N, VL(N, LINF));



	FOR(i, 0, M) {

		cin >> a[i] >> b[i] >> c[i];

		a[i]--, b[i]--;

		dist[a[i]][b[i]] = dist[b[i]][a[i]] = min((LL)c[i], dist[a[i]][b[i]]);

	}

	FOR(i, 0, N)dist[i][i] = 0;

	FOR(k, 0, N) {

		FOR(i, 0, N) {

			FOR(j, 0, N) {

				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

			}

		}

	}

	VVL d(1 << R, VL(R, LINF));

	FOR(i, 0, R) {

		d[1 << i][i] = 0;

	}



	FOR(state, 0, 1 << R) {

		FOR(k, 0, R) {

			if(state&(1<<k))

			FOR(i, 0, R) {

				if (!(state&(1 << i)))

					d[state | 1 << i][i] = min(d[state | 1 << i][i], d[state][k] + dist[r[k]][r[i]]);

			}

		}

	}

	ans = LINF;

	FOR(i, 0, R) {

		ans = min(ans, d[(1 << R) - 1][i]);

	}



	cout << ans << "\n";



	return 0;

}

