    }else{

      int r = root(par[x]);

      diff_weight[x] += diff_weight[par[x]];

      return par[x] = r;

    }

  }



  bool unite(int x, int y, int w = 0){

    w += weight(x); w -= weight(y);

    x = root(x);

    y = root(y);

    if(x == y) return false;

    if(rank[x] < rank[y]){

      par[x] = y;

      diff_weight[x] = -w;

    }else{

      par[y] = x;

      diff_weight[y] = w;

      if(rank[x] == rank[y]) rank[x]++;

    }

    return true;

  }



  bool same(int x, int y){

    return root(x) == root(y);

  }



  T weight(int x) {

    root(x);

    return diff_weight[x];

  }



  T diff(int x, int y) {

    return weight(y) - weight(x);

  }

};



