    lazy[x] += v; Max[x] += v;

}

inline void pushup(int x) {Max[x] = max(Max[x << 1], Max[x << 1 | 1]);}

inline void pushdown(int x) {

    if(lazy[x]) {

        update(x << 1, lazy[x]); update(x << 1 | 1, lazy[x]); lazy[x] = 0; 

    }

