    if(pq1.empty()||pq2.empty()) return;

    while(C2()(pq1.top(),pq2.top())){

      T t1=pq1.top();pq1.pop();

      T t2=pq2.top();pq2.pop();

      sum+=t1;

      sum-=t2;

      pq1.emplace(t2);

      pq2.emplace(t1);

    }

  }



  T query(){resolve();return sum;}



  void push(const T &x){pq1.emplace(x);}

  void expand(){num++;}

  void shrink(){assert(num);num--;}

};

