    s[i]=(char*)malloc((m+2)*sizeof(char));

  for(i=1;i<=n;i++)

    scanf("%s",s[i]+1);

}



void init()

{

  dis=(int**)malloc((n+1)*sizeof(int*));

  int i,j;

  for(i=1;i<=n;i++)

    dis[i]=(int*)malloc((m+1)*sizeof(int));

  for(i=1;i<=n;i++)

    for(j=1;j<=m;j++)

      dis[i][j]=INT_MAX;

  queuex=QueueInit();

  queuey=QueueInit();

  for(i=1;i<=n;i++)

    for(j=1;j<=m;j++)

      if(s[i][j] == 'S')

      {

        EnterQueue(i,queuex);

