inline int pt(int a[],int l,int r){

	int p,i,j;

	p=a[l];

	i=l;

	j=r+1;

	for(;;){

		while(a[++i]<p) if(i>=r) break;

		while(a[--j]>p) if(j<=l) break;

		if(i>=j) break;

		else swap(a[i],a[j]);

	}

	if(j==l) return j;

	swap(a[l],a[j]);

	return j;

}

