        vector<int>& vect = dict[w[1] + i];

        sort(vect.begin(), vect.end(), greater<int>());                     // descending order (greedy)

    }

    int max_value = 0;

    for (int a = 0; (size_t)a <= dict[w[1]].size(); a++) {                  // 'a': qty of w1

        if (a * w[1] > W)

            break;

        int value_a = 0;

        for (int i = 0; i < a; i++)

