	if (R <= mid)return b(n << 1, l, mid, L, R);

	else if (L > mid)return b(n << 1 | 1, mid + 1, r, L, R);

	return std::min(b(n << 1, l, mid, L, mid), b(n << 1 | 1, mid + 1, r, mid + 1, R));

}

