ld dfs1(int now, int pre){

    dp1[now] = 0.0;

    ld cnt = 0.0;

    for(auto &e: es[now]){

        if(e == pre) continue;

        cnt += 1.0;

        dp1[now] += dfs1(e, now)+1.0;

    }

    if(cnt > EPS) dp1[now] /= cnt;

    return dp1[now];

