void dfs2(int now, int pre){

    if(pre == -1) dp2[now] = 0.0;

    elif(pre == 0){

        ld n = sz(es[pre]);

        if(abs(n-1.0) < EPS) dp2[now] = 1.0;

        else dp2[now] = 2.0 + (dp1[pre]-dp1[now]/n-1.0)*n/(n-1);

    }

    else{

        ld n = sz(es[pre])-1;

        dp2[now] = 2.0 + (dp1[pre]-dp1[now]/n-1.0) + (dp2[pre]-1.0)/n;

