void dfs(int i, int p = -1) {

  int sz = (g[i].size() - (p != -1));

  for(int j : g[i]) if(j != p) {

    dfs(j, i);

    dp[i] += (1 + dp1[j]);

    dp1[i] += (1 + dp1[j]) / sz;

