    void Tarjan(int u)

    {

        dfn[u] = low[u] = ++tim;

        Stap[++Stop] = u;

        instack[u] = true;

        for(int v : E[u])

        {

            if(!dfn[v])

            {

                Tarjan(v);

                low[u] = min(low[u], low[v]);

            }

            else if(instack[v]) low[u] = min(low[u], dfn[v]);

        }

        for(int v : NE[u])

        {

            if(!dfn[v])

            {

                Tarjan(v);

                low[u] = min(low[u], low[v]);

            }

            else if(instack[v]) low[u] = min(low[u], dfn[v]);

        }

        if(u <= (N << 1))

        {

            int id = ceil(1. * u / 2), op = !(u & 1), val = a[id][op];

            for(int v : same[val])

            {

