                }

                else if(instack[v]) low[u] = min(low[u], dfn[v]);

            }

        }

        if(dfn[u] == low[u])

        {

            Bcnt++;

            int v;

            do

            {

                v = Stap[Stop--];

                instack[v] = false;

                Belong[v] = Bcnt;

            } while(u ^ v);

        }

    }

    inline bool check()

    {

        for(int i=1; i<=tot; i++)

        {

            NE[i].clear();

            dfn[i] = 0;

