    vector<ll> primes;  // primes[i] : i番目(iは0-index)の素数

    Eratosthenes(ll n = 1): n(n), f(n+1) {

        f[0] = f[1] = -1;

        for(ll i = 2; i <= n; ++i) {

            if(f[i]) {

                continue;

            } 

            primes.pb(i);

            f[i] = i;

            for(ll j = i*i; j <= n; j += i) {

                if(!f[j]) {

                    f[j] = i;

                } 

