        vector<ll> res;

        while(x != 1) {

            res.pb(f[x]);

            x /= f[x];

        }

        return res;

    }

    vector<P> factor(ll x) {  // (xのi番目の素因数, その素因数の個数)のvectorを返す(x = 720 = (2^4)*(3^2)*(5^1)なら{(2, 4), (3, 2), (5, 1)}のように)

        vector<ll> fL = factorList(x);

        if(fL.size() == 0) {

            return {};

        } 

        vector<P> res(1, make_pair(fL[0], 0));

        for(auto p : fL) {

            if(res.back().first == p) {

                res.back().second++;

            } 

            else {

                res.emplace_back(p, 1);

            }

        }

        return res;

    }

};



