using namespace std;

ll FastM(ll a, ll p, ll m){

	if(p == 0) return 1;

	ll r = a % m;

	ll k = 1;

	while(p > 1){

		if((p & 1) != 0){

			k = (k * r) % m;

		}

		r = (r * r) % m;

		p >>= 1;

	}

	return (r * k) % m;

}

