struct UnionFind {

	vector<int> data;

	UnionFind(int n) { data.assign(n, -1); }

	bool unionSet(int x, int y) {

		x = root(x); y = root(y);

		if (x != y) {

			if (data[y] < data[x]) swap(x, y);

			data[x] += data[y]; data[y] = x;

		}

		return x != y;

	}

