int main() {

    int N, A, B, C; cin >> N >> A >> B >> C;



    if(B % 2 == 1) {

        cout << 0 << endl;

        return 0;

    }



    Combination<mint> comb(10010);

    int q = B / 2;

    mint ans(0);

    for(int x=0; x<=C; x++) {

        for(int r=0; r<=min(A, C); r++) {

            if((C - x - r) < 0 or (C - x - r) % 3 != 0) continue;



            int p = A - r;

            int s = (C - x - r) / 3;



            mint mul(1);

            mul *= comb.H(q, x);

            mul *= comb.H(q+1, r);

            mul *= comb.H(q+1+r, s);

            mul *= comb.H(q+1+r+s, p);

            ans += mul;

        }

    }

    cout << ans << endl;

    return 0;

}

