vector<int> adj[MAXN];



inline bool dfs(int u, int fa) {

//cout << u << " -------- " << fa << endl;

	if (val[u] == INF) {

		l[u] = -INF, r[u] = INF;

		odd[u] = -1;

	} else {

		l[u] = r[u] = val[u];

		odd[u] = val[u] & 1;

	}

	for (int i = 0; i < adj[u].size(); ++i) {

	int v = adj[u][i];

//cout << "e: " << u << " " << v << endl;

		if (v != fa) {

			if (!dfs(v, u)) {

				return false;

			}

			int ll = l[v] - 1, rr = r[v] + 1;

			int o = odd[v] == -1 ? -1 : odd[v] ^ 1;

			l[u] = max(l[u], ll);

			r[u] = min(r[u], rr);

			if (l[u] > r[u]) {

				return false;

			}

			if (o == -1) {

				continue;

			}

			if (odd[u] == -1) {

				odd[u] = o;

			} else {

				if (o != odd[u]) {

					return false;

				}

			}

//cout << l[u] << " " << r[u] << " " << odd[u] << " " << o << endl;

			if (odd[u] != -1) {

				int t1 = l[u], t2 = min(l[u] + 1, r[u]);

