        int t = (long long) f[k + len] * g[wn] % P;

        f[k + len] = (f[k] - t) % P;

        if (f[k + len] < 0) {

          f[k + len] += P;

        }

        f[k] = (f[k] + t) % P;

        wn += o * (1 << bit - i - 1);                        

        if (wn < 0) {

          wn += lim;

        }

      }

    }

  }

}



