ケツに着目すると、L以上のものがつながっていないといけない。

逆にこれが繋がっているときはどう切ってもいいので、Lの周りをはしから削除していく。



----解説ここまで---- */



LL N, L;





int main() {

	cin.tie(0);

	ios_base::sync_with_stdio(false);



	cin >> N >> L;

	VL a(N);

	FOR(i, 0, N) {

		cin >> a[i];

	}

	LL pos = -1;

	FOR(i, 0, N - 1) {

		if (a[i] + a[i + 1] >= L) {

			pos = i;

		}

	}

	if (pos == -1) {

		cout << "Impossible" << endl;

	}

	else {

		cout << "Possible" << endl;

		VI ans(N - 1);

		FOR(i, 0, pos) {

			cout << i + 1 << " ";

		}

		FORR(i, N - 1, pos) {

			cout << i << " ";



		}cout << endl;

	}



	return 0;

}

