ll quick_pow(ll a, ll b) {

    ll ret = 1;

    for (; b; b >>= 1) {

        if (b & 1) ret = ret * a % mod;

        a = a * a % mod;

    } return ret;

}



void pre() {

    fac[0] = inv[0] = 1;

    rep(i, 1, n * K) fac[i] = fac[i - 1] * i % mod;

