    for (int i = n * K - 1; i >= 1; i--) inv[i] = inv[i + 1] * (i + 1) % mod;

}



ll C(ll n, ll m) { return fac[n] * inv[m] % mod * inv[n - m] % mod; }



ll upd(ll x, ll y) { return (x + y) % mod; }



