	{

		x=sum(1,n,pos[i]+1,mi(pos[i]+m-1,n),1);

		if(x<2e9) add(pos[i],pos[x]);

		x=sum(1,n,mx(pos[i]-m+1,1),pos[i]-1,1);

		if(x<2e9) add(pos[i],pos[x]);

		upd(1,n,pos[i],i,1);

	}

