void ins(int x){

	heap[++top]=x;int k=top;

	while(k>1){

		if(heap[k>>1]>heap[k])swap(heap[k],heap[k>>1]);

		else break;

		k>>=1;

	}

}

void pop(){

	heap[1]=heap[top];int k=1;top--;

	while((k<<1)<=top){

		int v=k<<1;

		if(v<top)if(heap[v|1]<heap[v])v|=1;

		if(heap[v]<heap[k])swap(heap[k],heap[v]);

		else break;

		k=v;

	}

}

